import java.io.File;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import net.runelite.cache.AreaManager;
import net.runelite.cache.EntityOpsDefinition;
import net.runelite.cache.NpcManager;
import net.runelite.cache.ObjectManager;
import net.runelite.cache.WorldMapManager;
import net.runelite.cache.definitions.AreaDefinition;
import net.runelite.cache.definitions.NpcDefinition;
import net.runelite.cache.definitions.ObjectDefinition;
import net.runelite.cache.definitions.WorldMapElementDefinition;
import net.runelite.cache.fs.Store;
import net.runelite.cache.region.Position;

/**
 * Offline reconnaissance against the local OSRS cache.
 *
 * <p>Run once, by hand, to harvest the identifiers for Golem Crafting so they can be
 * hardcoded into the plugin. Nothing here ships — it exists so that the plugin does
 * not have to discover at runtime what the cache already knows.
 *
 * <p>The cache is the right source for most of it. {@code NpcDefinition} carries the
 * standing, walking and run animation IDs, which the RuneLite client API does not
 * expose on {@code NPCComposition} at all — so what would otherwise have to be read
 * off a live actor is simply readable here.
 *
 * <pre>
 * javac -cp cache-jar-with-dependencies.jar CacheRecon.java
 * java  -cp cache-jar-with-dependencies.jar;. CacheRecon &lt;cache-dir&gt;
 * </pre>
 */
public class CacheRecon
{
	/** Names worth reporting. Deliberately wide: better a long list than a missed golem. */
	private static final String[] NPC_TERMS = {"golem", "wyrmscraig", "clay", "stone chunk"};
	private static final String[] OBJECT_TERMS = {"golem", "plinth", "wyrmscraig", "chunk"};
	private static final String[] MAP_TERMS = {"wyrmscraig", "golem"};

	public static void main(String[] args) throws Exception
	{
		File cacheDir = new File(args.length > 0
			? args[0]
			: System.getProperty("user.home") + "/.runelite/jagexcache/oldschool/LIVE");

		System.out.println("Cache: " + cacheDir.getAbsolutePath());
		System.out.println();

		try (Store store = new Store(cacheDir))
		{
			store.load();

			dumpNpcs(store);
			dumpObjects(store);
			dumpMapElements(store);
		}
	}

	private static void dumpNpcs(Store store) throws Exception
	{
		NpcManager npcs = new NpcManager(store);
		npcs.load();

		System.out.println("=== NPCs ===");
		List<NpcDefinition> hits = new ArrayList<>();
		for (NpcDefinition npc : npcs.getNpcs())
		{
			if (matches(npc.name, NPC_TERMS))
			{
				hits.add(npc);
			}
		}
		hits.sort((a, b) -> Integer.compare(a.id, b.id));

		for (NpcDefinition npc : hits)
		{
			System.out.printf(
				"id=%-6d name=%-28s size=%d stand=%-6d walk=%-6d run=%-6d "
					+ "rotL=%-6d rotR=%-6d rot180=%-6d wScale=%d hScale=%d%n",
				npc.id, npc.name, npc.size,
				npc.standingAnimation, npc.walkingAnimation, npc.runAnimation,
				npc.rotateLeftAnimation, npc.rotateRightAnimation, npc.rotate180Animation,
				npc.widthScale, npc.heightScale);
			System.out.printf("        models=%s recolourFrom=%s recolourTo=%s actions=%s%n",
				Arrays.toString(npc.models),
				Arrays.toString(npc.recolorToFind),
				Arrays.toString(npc.recolorToReplace),
				describeOps(npc.ops));
		}
		System.out.println("(" + hits.size() + " matching NPCs)");
		System.out.println();
	}

	private static void dumpObjects(Store store) throws Exception
	{
		ObjectManager objects = new ObjectManager(store);
		objects.load();

		System.out.println("=== Objects ===");
		int count = 0;
		for (ObjectDefinition obj : objects.getObjects())
		{
			if (!matches(obj.getName(), OBJECT_TERMS))
			{
				continue;
			}
			count++;
			System.out.printf("id=%-6d name=%-30s size=%dx%d actions=%s%n",
				obj.getId(), obj.getName(),
				obj.getSizeX(), obj.getSizeY(),
				describeOps(obj.getOps()));
		}
		System.out.println("(" + count + " matching objects)");
		System.out.println();
	}

	/**
	 * World map labels, which is how the island's location is found without anyone
	 * having to stand on it and read a coordinate off the screen.
	 */
	private static void dumpMapElements(Store store) throws Exception
	{
		// World map elements carry only an area ID; the label lives on the area
		// definition, so both have to be loaded and joined.
		AreaManager areas = new AreaManager(store);
		areas.load();

		System.out.println("=== Named areas ===");
		int named = 0;
		for (AreaDefinition area : areas.getAreas())
		{
			if (matches(area.name, MAP_TERMS))
			{
				named++;
				System.out.printf("areaId=%-6d name=%s%n", area.id, area.name);
			}
		}
		System.out.println("(" + named + " matching areas)");
		System.out.println();

		WorldMapManager maps = new WorldMapManager(store);
		maps.load();

		System.out.println("=== World map elements for those areas ===");
		int count = 0;
		for (WorldMapElementDefinition element : maps.getElements())
		{
			AreaDefinition area = areas.getArea(element.getAreaDefinitionId());
			if (area == null || !matches(area.name, MAP_TERMS))
			{
				continue;
			}
			count++;
			Position at = element.getWorldPosition();
			if (at == null)
			{
				System.out.printf("name=%-30s (no position)%n", area.name);
				continue;
			}
			int regionId = (at.getX() >> 6) << 8 | (at.getY() >> 6);
			System.out.printf("name=%-30s world=(%d,%d,%d) region=%d%n",
				area.name, at.getX(), at.getY(), at.getZ(), regionId);
		}
		System.out.println("(" + count + " matching map elements)");
	}

	/**
	 * Right-click options as a flat list. Newer caches moved these off a plain
	 * String[] and onto a structured ops object, so they have to be walked out.
	 */
	private static String describeOps(EntityOpsDefinition ops)
	{
		if (ops == null || ops.getOps() == null || ops.getOps().isEmpty())
		{
			return "[]";
		}
		List<String> out = new ArrayList<>();
		for (EntityOpsDefinition.Op op : ops.getOps())
		{
			if (op != null && op.text != null)
			{
				out.add(op.text);
			}
		}
		return out.toString();
	}

	private static boolean matches(String name, String[] terms)
	{
		if (name == null || name.equals("null"))
		{
			return false;
		}
		String lower = name.toLowerCase(Locale.ROOT);
		for (String term : terms)
		{
			if (lower.contains(term))
			{
				return true;
			}
		}
		return false;
	}
}

import java.io.File;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.runelite.cache.ConfigType;
import net.runelite.cache.IndexType;
import net.runelite.cache.definitions.SequenceDefinition;
import net.runelite.cache.definitions.loaders.SequenceLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;
import net.runelite.cache.region.Location;
import net.runelite.cache.region.Region;
import net.runelite.cache.region.RegionLoader;

/**
 * Second reconnaissance pass: animations and world placement.
 *
 * <p>The first pass ({@code CacheRecon}) established that the crafted golem is NPC
 * 16304, walking on 14452 and standing on 14453. Two things it could not answer are
 * settled here.
 *
 * <p>The <b>death animation</b> is not on the NPC definition — nothing is, beyond the
 * gait, because a crumble is played by a script rather than declared as a pose. But
 * it is certainly in the same authoring block as the golem's own animations, so the
 * sequences either side are dumped with their frame counts and total durations. A
 * crumble is short, plays once and does not loop, which separates it from the walk
 * and idle cycles at a glance.
 *
 * <p>The <b>crafting site</b> is found by sweeping every region for the plinth object
 * IDs. That pins the exact tiles the activity happens on, and therefore which regions
 * the island actually occupies — which is what the free-roam map has to cover.
 */
public class RegionRecon
{
	/** The animation block the golem's own sequences sit in. */
	private static final int SEQ_FROM = 14440;
	private static final int SEQ_TO = 14470;

	/** The Golem Crafting object chain, from CacheRecon. */
	private static final int[] CRAFTING_OBJECTS = {62353, 62354, 62355, 62356, 62357, 62358};

	/** Wyrmscraig, per the world map element. */
	private static final int WYRMSCRAIG_REGION = 10275;

	public static void main(String[] args) throws Exception
	{
		File cacheDir = new File(args.length > 0
			? args[0]
			: System.getProperty("user.home") + "/.runelite/jagexcache/oldschool/LIVE");

		try (Store store = new Store(cacheDir))
		{
			store.load();

			dumpSequences(store);
			sweepRegions(store);
		}
	}

	private static void dumpSequences(Store store) throws Exception
	{
		Storage storage = store.getStorage();
		Index index = store.getIndex(IndexType.CONFIGS);
		Archive archive = index.getArchive(ConfigType.SEQUENCE.getId());
		byte[] data = storage.loadArchive(archive);
		ArchiveFiles files = archive.getFiles(data);

		SequenceLoader loader = new SequenceLoader();

		System.out.println("=== Sequences " + SEQ_FROM + ".." + SEQ_TO + " ===");
		System.out.println("id      frames  duration(cycles)  frameStep  maxLoops  note");

		for (FSFile f : files.getFiles())
		{
			int id = f.getFileId();
			if (id < SEQ_FROM || id > SEQ_TO)
			{
				continue;
			}

			SequenceDefinition seq;
			try
			{
				seq = loader.load(id, f.getContents());
			}
			catch (RuntimeException e)
			{
				System.out.printf("%-7d (unreadable: %s)%n", id, e);
				continue;
			}

			int frames = seq.frameIDs == null ? 0 : seq.frameIDs.length;
			int duration = 0;
			if (seq.frameLengths != null)
			{
				for (int len : seq.frameLengths)
				{
					duration += len;
				}
			}

			System.out.printf("%-7d %-7d %-17d %-10d %-9d %s%n",
				id, frames, duration, seq.frameStep, seq.maxLoops, note(id));
		}
		System.out.println();
	}

	private static String note(int id)
	{
		switch (id)
		{
			case 14449:
				return "<- Wyrmscraig Goat walk";
			case 14452:
				return "<- GOLEM WALK (npc 16304)";
			case 14453:
				return "<- GOLEM IDLE (npc 16304)";
			case 14456:
				return "<- Broken/Powered golem stand";
			default:
				return "";
		}
	}

	/**
	 * Sweeps every region in the cache for the crafting objects, and reports what is
	 * around Wyrmscraig.
	 *
	 * <p>Locations are XTEA-encrypted per region. Regions whose key is unknown simply
	 * fail to decode and are counted rather than reported — a region that will not
	 * open is not evidence of anything, and pretending otherwise would put phantom
	 * holes in the island map.
	 */
	private static void sweepRegions(Store store) throws Exception
	{
		// Zero keys. Plenty of regions are unencrypted or keyed with zeros; the rest
		// will fail to decode and are counted separately.
		RegionLoader loader = new RegionLoader(store, regionId -> new int[4]);
		loader.loadRegions();

		Map<Integer, List<String>> craftingHits = new TreeMap<>();
		Map<Integer, Integer> islandRegions = new TreeMap<>();
		int total = 0;

		int anchorRx = WYRMSCRAIG_REGION >> 8;
		int anchorRy = WYRMSCRAIG_REGION & 0xFF;

		for (Region region : loader.getRegions())
		{
			total++;

			int rx = region.getRegionX();
			int ry = region.getRegionY();
			if (Math.abs(rx - anchorRx) <= 4 && Math.abs(ry - anchorRy) <= 4)
			{
				islandRegions.put(region.getRegionID(), walkableTiles(region));
			}

			for (Location loc : region.getLocations())
			{
				for (int wanted : CRAFTING_OBJECTS)
				{
					if (loc.getId() == wanted)
					{
						craftingHits
							.computeIfAbsent(region.getRegionID(), k -> new ArrayList<>())
							.add(String.format("obj %d at (%d,%d,%d) type=%d",
								loc.getId(),
								loc.getPosition().getX(), loc.getPosition().getY(),
								loc.getPosition().getZ(), loc.getType()));
					}
				}
			}
		}

		System.out.println("=== Crafting objects in the world ===");
		if (craftingHits.isEmpty())
		{
			System.out.println("(none found - the site's region is probably XTEA-locked,");
			System.out.println(" or the objects are spawned by script rather than placed in the map)");
		}
		for (Map.Entry<Integer, List<String>> entry : craftingHits.entrySet())
		{
			System.out.println("region " + entry.getKey() + ":");
			for (String hit : entry.getValue())
			{
				System.out.println("    " + hit);
			}
		}
		System.out.println();

		System.out.println("=== Regions around Wyrmscraig (" + WYRMSCRAIG_REGION + ") ===");
		System.out.println("region  regionX,regionY  baseX,baseY   walkable tiles (plane 0)");
		for (Map.Entry<Integer, Integer> entry : islandRegions.entrySet())
		{
			int id = entry.getKey();
			int rx = id >> 8;
			int ry = id & 0xFF;
			System.out.printf("%-7d %-16s %-13s %d%n",
				id, rx + "," + ry, (rx << 6) + "," + (ry << 6), entry.getValue());
		}
		System.out.println();
		System.out.println("(" + total + " regions in cache, " + islandRegions.size() + " near Wyrmscraig)");
	}

	/**
	 * Tiles on plane 0 that are not flagged as blocked terrain.
	 *
	 * <p>A rough measure, deliberately. It counts ground the engine considers
	 * standable before objects are taken into account, which is enough to tell an
	 * inhabited region from open sea.
	 */
	private static int walkableTiles(Region region)
	{
		int count = 0;
		for (int x = 0; x < Region.X; x++)
		{
			for (int y = 0; y < Region.Y; y++)
			{
				if ((region.getTileSetting(0, x, y) & 1) == 0)
				{
					count++;
				}
			}
		}
		return count;
	}
}

import java.io.File;
import java.util.List;
import java.util.Map;
import net.runelite.cache.EntityOpsDefinition;
import net.runelite.cache.NpcManager;
import net.runelite.cache.definitions.NpcDefinition;
import net.runelite.cache.fs.Store;

/**
 * Dumps every right-click option and parameter on the golem.
 *
 * <p>The first recon pass reported the golem as having no options at all, which the
 * game contradicts. The reason is that newer caches carry four kinds of op —
 * unconditional, sub, conditional, and conditional-sub — and only the first was being
 * read. A conditional op is one the client shows or hides based on a varbit or varp,
 * which is exactly how an option that only appears for the player who made the golem
 * would be authored.
 *
 * <p>Examine text is looked for in the definition's params, where per-entity strings
 * live.
 *
 * <pre>
 * java GolemOps &lt;cache-dir&gt; [npcId...]
 * </pre>
 */
public class GolemOps
{
	private static final int DEFAULT_NPC = 16304;

	public static void main(String[] args) throws Exception
	{
		File cacheDir = new File(args.length > 0
			? args[0]
			: System.getProperty("user.home") + "/.runelite/jagexcache/oldschool/LIVE");

		int[] ids;
		if (args.length > 1)
		{
			ids = new int[args.length - 1];
			for (int i = 1; i < args.length; i++)
			{
				ids[i - 1] = Integer.parseInt(args[i]);
			}
		}
		else
		{
			// The crafted golem, plus the two static ones nearby for comparison.
			ids = new int[]{DEFAULT_NPC, 16321, 16322};
		}

		try (Store store = new Store(cacheDir))
		{
			store.load();
			NpcManager npcs = new NpcManager(store);
			npcs.load();

			for (int id : ids)
			{
				NpcDefinition npc = npcs.get(id);
				if (npc == null)
				{
					System.out.println("npc " + id + ": not in cache");
					continue;
				}
				dump(npc);
			}
		}
	}

	private static void dump(NpcDefinition npc)
	{
		System.out.println();
		System.out.println("=== npc " + npc.id + "  \"" + npc.name + "\" ===");

		EntityOpsDefinition ops = npc.ops;
		if (ops == null)
		{
			System.out.println("  (no ops object at all)");
		}
		else
		{
			dumpOps(ops);
		}

		System.out.println("  params:");
		Map<Integer, Object> params = npc.params;
		if (params == null || params.isEmpty())
		{
			System.out.println("    (none)");
		}
		else
		{
			for (Map.Entry<Integer, Object> entry : params.entrySet())
			{
				System.out.printf("    %-8d %s%n", entry.getKey(), entry.getValue());
			}
		}

		System.out.println("  category=" + npc.category
			+ " interactable=" + npc.isInteractable
			+ " minimapVisible=" + npc.isMinimapVisible
			+ " combatLevel=" + npc.combatLevel);
	}

	private static void dumpOps(EntityOpsDefinition ops)
	{
		System.out.println("  unconditional ops:");
		List<EntityOpsDefinition.Op> plain = ops.getOps();
		if (plain == null || plain.isEmpty())
		{
			System.out.println("    (none)");
		}
		else
		{
			for (int i = 0; i < plain.size(); i++)
			{
				EntityOpsDefinition.Op op = plain.get(i);
				System.out.printf("    slot %d: %s%n", i, op == null ? "-" : quote(op.text));
			}
		}

		System.out.println("  conditional ops:");
		List<List<EntityOpsDefinition.ConditionalOp>> conditional = ops.getConditionalOps();
		boolean anyConditional = false;
		if (conditional != null)
		{
			for (int slot = 0; slot < conditional.size(); slot++)
			{
				List<EntityOpsDefinition.ConditionalOp> forSlot = conditional.get(slot);
				if (forSlot == null)
				{
					continue;
				}
				for (EntityOpsDefinition.ConditionalOp op : forSlot)
				{
					if (op == null)
					{
						continue;
					}
					anyConditional = true;
					System.out.printf("    slot %d: %-24s when varbit=%d varp=%d in [%d..%d]%n",
						slot, quote(op.text), op.varbitID, op.varpID, op.minValue, op.maxValue);
				}
			}
		}
		if (!anyConditional)
		{
			System.out.println("    (none)");
		}

		System.out.println("  sub ops:");
		List<List<EntityOpsDefinition.SubOp>> subs = ops.getSubOps();
		boolean anySub = false;
		if (subs != null)
		{
			for (int slot = 0; slot < subs.size(); slot++)
			{
				List<EntityOpsDefinition.SubOp> forSlot = subs.get(slot);
				if (forSlot == null)
				{
					continue;
				}
				for (EntityOpsDefinition.SubOp op : forSlot)
				{
					if (op == null)
					{
						continue;
					}
					anySub = true;
					System.out.printf("    slot %d sub %d: %s%n", slot, op.subID, quote(op.text));
				}
			}
		}
		if (!anySub)
		{
			System.out.println("    (none)");
		}
	}

	private static String quote(String text)
	{
		return text == null ? "null" : '"' + text + '"';
	}
}

import java.io.DataOutputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.zip.GZIPOutputStream;

/**
 * Turns a recon log into the island map the plugin ships.
 *
 * <p>The collision for Wyrmscraig cannot be read from the game cache: object
 * locations are XTEA-encrypted and the available key file predates the content. The
 * live client has them decrypted the moment a region loads, so recon mode dumps the
 * real thing as the player walks. This folds those dumps into one file, keeping the
 * most complete observation of each region.
 *
 * <p>Also renders the result as text, because a map with a hole in it is obvious to
 * look at and invisible in a tile count.
 *
 * <pre>
 * java ReconToMap &lt;recon.log&gt; [out.gz]
 * </pre>
 */
public class ReconToMap
{
	private static final int REGION_SIZE = 64;
	private static final int BYTES_PER_REGION = REGION_SIZE * REGION_SIZE * 2 / 8;

	/** The plinth, from the golem spawn positions in the log. */
	private static final int PLINTH_X = 2596;
	private static final int PLINTH_Y = 2257;

	/** Best observation of each region-plane, keyed as region<<4|plane. */
	private static final Map<Integer, byte[]> bits = new TreeMap<>();
	private static final Map<Integer, Integer> seen = new HashMap<>();

	public static void main(String[] args) throws Exception
	{
		if (args.length < 1)
		{
			System.err.println("usage: ReconToMap <recon.log> [out.gz]");
			return;
		}

		List<String> lines = Files.readAllLines(new File(args[0]).toPath(), StandardCharsets.UTF_8);
		int collisionLines = 0;

		for (String line : lines)
		{
			if (!line.startsWith("COLLISION\t"))
			{
				continue;
			}
			collisionLines++;

			Map<String, String> f = fields(line);
			int region = Integer.parseInt(f.get("region"));
			int plane = Integer.parseInt(f.get("plane"));
			int tiles = Integer.parseInt(f.get("tilesSeen"));
			int key = region << 4 | plane;

			// Keep the most complete observation. A region is dumped every time the
			// player is near it and only fully covered when they stand well inside it,
			// so the last dump is not necessarily the best one.
			Integer bestSoFar = seen.get(key);
			if (bestSoFar != null && bestSoFar >= tiles)
			{
				continue;
			}
			seen.put(key, tiles);
			bits.put(key, unhex(f.get("bits")));
		}

		System.out.println("collision lines read: " + collisionLines);
		System.out.println("region-planes kept:   " + bits.size());
		System.out.println();

		report();
		render();

		File out = new File(args.length > 1 ? args[1] : "island-map.gz");
		write(out);
		System.out.println();
		System.out.println("wrote " + out.getAbsolutePath() + " (" + out.length() + " bytes)");
	}

	private static void report()
	{
		System.out.println("region  plane  tilesSeen  walkable  complete");
		int totalWalkable = 0;
		for (Map.Entry<Integer, byte[]> entry : bits.entrySet())
		{
			int region = entry.getKey() >> 4;
			int plane = entry.getKey() & 0xF;
			int tiles = seen.get(entry.getKey());
			int walkable = countWalkable(entry.getValue());
			totalWalkable += walkable;
			System.out.printf("%-7d %-6d %-10d %-9d %s%n",
				region, plane, tiles, walkable, tiles == REGION_SIZE * REGION_SIZE ? "yes" : "PARTIAL");
		}
		System.out.println();
		System.out.println("total walkable tiles: " + totalWalkable);
		System.out.println();
	}

	/**
	 * Draws the 2x2 region block around the crafting site, two world tiles per
	 * character so it fits a terminal.
	 */
	private static void render()
	{
		int minX = 2496, maxX = 2623, minY = 2176, maxY = 2303;

		System.out.println("Island around the plinth  ('#' walkable, '.' mapped but blocked, ' ' unmapped, 'P' plinth)");
		System.out.println("X " + minX + ".." + maxX + "   Y " + minY + ".." + maxY + "   (2 tiles per character)");

		for (int y = maxY; y >= minY; y -= 2)
		{
			StringBuilder row = new StringBuilder();
			for (int x = minX; x <= maxX; x += 2)
			{
				if (Math.abs(x - PLINTH_X) <= 1 && Math.abs(y - PLINTH_Y) <= 1)
				{
					row.append('P');
					continue;
				}

				int region = ((x >> 6) << 8) | (y >> 6);
				byte[] data = bits.get(region << 4);
				if (data == null)
				{
					row.append(' ');
					continue;
				}
				row.append(walkable(data, x & 63, y & 63) ? '#' : '.');
			}
			System.out.println(row);
		}
	}

	// ---- bit plumbing, matching IslandMemory's layout ----

	private static boolean walkable(byte[] data, int rx, int ry)
	{
		int bit = (ry * REGION_SIZE + rx) * 2;
		return get(data, bit) || get(data, bit + 1);
	}

	private static boolean get(byte[] data, int bit)
	{
		return (data[bit >> 3] >> (bit & 7) & 1) != 0;
	}

	private static int countWalkable(byte[] data)
	{
		int count = 0;
		for (int rx = 0; rx < REGION_SIZE; rx++)
		{
			for (int ry = 0; ry < REGION_SIZE; ry++)
			{
				if (walkable(data, rx, ry))
				{
					count++;
				}
			}
		}
		return count;
	}

	private static byte[] unhex(String hex)
	{
		byte[] out = new byte[hex.length() / 2];
		for (int i = 0; i < out.length; i++)
		{
			out[i] = (byte) Integer.parseInt(hex.substring(i * 2, i * 2 + 2), 16);
		}
		if (out.length != BYTES_PER_REGION)
		{
			throw new IllegalArgumentException("expected " + BYTES_PER_REGION + " bytes, got " + out.length);
		}
		return out;
	}

	/**
	 * Writes the bundled form: gzipped region-plane records. Passability maps are
	 * long runs of the same answer, so this compresses to a fraction of its size —
	 * the difference between a resource and an embarrassment.
	 */
	private static void write(File file) throws IOException
	{
		try (DataOutputStream out = new DataOutputStream(
			new GZIPOutputStream(new FileOutputStream(file))))
		{
			out.writeInt(bits.size());
			for (Map.Entry<Integer, byte[]> entry : bits.entrySet())
			{
				out.writeInt(entry.getKey() >> 4);
				out.writeInt(entry.getKey() & 0xF);
				out.write(entry.getValue());
			}
		}
	}

	private static Map<String, String> fields(String line)
	{
		Map<String, String> out = new HashMap<>();
		for (String part : line.split("\t"))
		{
			int eq = part.indexOf('=');
			if (eq > 0)
			{
				out.put(part.substring(0, eq), part.substring(eq + 1));
			}
		}
		return out;
	}
}

import java.io.ByteArrayOutputStream;
import java.io.DataOutputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.BitSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.zip.GZIPOutputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

/**
 * Builds the island passability map the plugin ships, from the Shortest Path
 * collision map, and checks it against a recon log before trusting it.
 *
 * <p>Shortest Path publishes a whole-world collision map generated from the game
 * cache with the XTEA keys it has. That is the only route to a Wyrmscraig map that
 * does not require the player to walk the island first — the local cache's object
 * locations are encrypted and the available key file predates the content.
 *
 * <p>It is not taken on trust. A downloaded map could easily predate the content, in
 * which case its Wyrmscraig regions exist but describe empty ground, and golems would
 * be given the run of an island the map thinks is featureless. So it is cross-checked
 * against the real collision recorded in game, tile by tile, over the regions recon
 * covered completely. Agreement means the map is current; disagreement means it is
 * not, and says so rather than shipping it.
 *
 * <p>Both formats are the same two-bits-per-tile north/east scheme, so the comparison
 * is direct.
 *
 * <pre>
 * java BuildIslandMap &lt;collision-map.zip&gt; &lt;recon.log&gt; &lt;out.gz&gt;
 * </pre>
 */
public class BuildIslandMap
{
	private static final int REGION_SIZE = 64;
	private static final int BYTES_PER_PLANE = REGION_SIZE * REGION_SIZE * 2 / 8;

	/**
	 * The block of regions clipped out as "the island".
	 *
	 * <p>Wyrmscraig's world map label is at (2600, 2240), region 10275 = (40, 35).
	 * The surrounding regions with authored terrain run (39..41, 34..36), which is
	 * what the recon lap loaded. Clipping to that keeps the resource small; the whole
	 * world map is 1.2MB and all but a corner of it is somewhere golems will never be.
	 */
	private static final int MIN_RX = 39, MAX_RX = 41;
	private static final int MIN_RY = 34, MAX_RY = 36;

	private static final int PLINTH_X = 2596, PLINTH_Y = 2257;

	public static void main(String[] args) throws Exception
	{
		if (args.length < 3)
		{
			System.err.println("usage: BuildIslandMap <collision-map.zip> <recon.log> <out.gz>");
			return;
		}

		Map<Integer, byte[]> world = readShortestPath(new File(args[0]));
		System.out.println("shortest path map: " + world.size() + " regions");

		Map<Integer, byte[]> recon = readRecon(new File(args[1]));
		System.out.println("recon log:         " + recon.size() + " complete regions");
		System.out.println();

		boolean trustworthy = validate(world, recon);

		Map<Integer, byte[]> island = clip(world);
		System.out.println();
		System.out.println("island clip: regions " + MIN_RX + ".." + MAX_RX + " x " + MIN_RY + ".." + MAX_RY
			+ " = " + island.size() + " regions");
		render(island);

		if (!trustworthy)
		{
			System.out.println();
			System.out.println("NOT WRITING: the downloaded map disagrees with what was seen in game.");
			System.out.println("It most likely predates Wyrmscraig. Use the recon-harvested map instead.");
			return;
		}

		File out = new File(args[2]);
		write(island, out);
		System.out.println();
		System.out.println("wrote " + out.getAbsolutePath() + " (" + out.length() + " bytes)");
	}

	/**
	 * Compares the downloaded map against the regions recon mapped completely.
	 *
	 * @return true if they agree well enough to ship the downloaded map
	 */
	private static boolean validate(Map<Integer, byte[]> world, Map<Integer, byte[]> recon)
	{
		System.out.println("=== validation against live collision ===");
		System.out.println("region  tiles  agree   disagree  agreement");

		int totalAgree = 0, totalTiles = 0;
		boolean any = false;

		for (Map.Entry<Integer, byte[]> entry : recon.entrySet())
		{
			byte[] theirs = world.get(entry.getKey());
			if (theirs == null)
			{
				System.out.printf("%-7d (absent from downloaded map)%n", entry.getKey());
				continue;
			}
			any = true;

			byte[] mine = entry.getValue();
			int agree = 0;
			for (int rx = 0; rx < REGION_SIZE; rx++)
			{
				for (int ry = 0; ry < REGION_SIZE; ry++)
				{
					if (walkable(mine, rx, ry) == walkable(theirs, rx, ry))
					{
						agree++;
					}
				}
			}

			int tiles = REGION_SIZE * REGION_SIZE;
			totalAgree += agree;
			totalTiles += tiles;
			System.out.printf("%-7d %-6d %-7d %-9d %.1f%%%n",
				entry.getKey(), tiles, agree, tiles - agree, 100.0 * agree / tiles);
		}

		if (!any || totalTiles == 0)
		{
			System.out.println("no overlap to check - cannot validate");
			return false;
		}

		double overall = 100.0 * totalAgree / totalTiles;
		System.out.printf("overall agreement: %.1f%%%n", overall);

		// A map generated from the same cache should agree almost exactly; the slack
		// is for objects that vary with a player's game state, which the live scene
		// reflects and a static export cannot.
		boolean ok = overall >= 95.0;
		System.out.println(ok
			? "-> downloaded map matches the live island. Current."
			: "-> downloaded map does NOT match. Stale, or a different place.");
		return ok;
	}

	private static Map<Integer, byte[]> clip(Map<Integer, byte[]> world)
	{
		Map<Integer, byte[]> out = new TreeMap<>();
		for (int rx = MIN_RX; rx <= MAX_RX; rx++)
		{
			for (int ry = MIN_RY; ry <= MAX_RY; ry++)
			{
				int region = (rx << 8) | ry;
				byte[] data = world.get(region);
				if (data != null)
				{
					out.put(region, data);
				}
			}
		}
		return out;
	}

	private static void render(Map<Integer, byte[]> island)
	{
		int minX = MIN_RX << 6, maxX = ((MAX_RX + 1) << 6) - 1;
		int minY = MIN_RY << 6, maxY = ((MAX_RY + 1) << 6) - 1;

		System.out.println();
		System.out.println("('#' walkable, '.' blocked, ' ' no data, 'P' plinth)  3 tiles per character");
		for (int y = maxY; y >= minY; y -= 3)
		{
			StringBuilder row = new StringBuilder();
			for (int x = minX; x <= maxX; x += 3)
			{
				if (Math.abs(x - PLINTH_X) <= 2 && Math.abs(y - PLINTH_Y) <= 2)
				{
					row.append('P');
					continue;
				}
				byte[] data = island.get(((x >> 6) << 8) | (y >> 6));
				row.append(data == null ? ' ' : walkable(data, x & 63, y & 63) ? '#' : '.');
			}
			System.out.println(row);
		}
	}

	// ---- readers ----

	/** Shortest Path's zip: one entry per region, named {@code regionX_regionY}. */
	private static Map<Integer, byte[]> readShortestPath(File zip) throws IOException
	{
		Map<Integer, byte[]> out = new HashMap<>();
		try (ZipInputStream in = new ZipInputStream(Files.newInputStream(zip.toPath())))
		{
			ZipEntry entry;
			while ((entry = in.getNextEntry()) != null)
			{
				String[] parts = entry.getName().split("_");
				if (parts.length != 2)
				{
					continue;
				}
				int rx = Integer.parseInt(parts[0]);
				int ry = Integer.parseInt(parts[1]);

				// Only plane 0 is kept. Golem Crafting happens at ground level and
				// carrying three unused floors would triple the resource.
				byte[] all = readAll(in);
				byte[] plane0 = new byte[BYTES_PER_PLANE];
				System.arraycopy(BitSet.valueOf(all).toByteArray(), 0, plane0, 0,
					Math.min(BYTES_PER_PLANE, BitSet.valueOf(all).toByteArray().length));
				out.put((rx << 8) | ry, plane0);
			}
		}
		return out;
	}

	/** Recon log: only regions observed complete are usable as ground truth. */
	private static Map<Integer, byte[]> readRecon(File log) throws IOException
	{
		Map<Integer, byte[]> out = new TreeMap<>();
		for (String line : Files.readAllLines(log.toPath(), StandardCharsets.UTF_8))
		{
			if (!line.startsWith("COLLISION\t"))
			{
				continue;
			}
			Map<String, String> f = new HashMap<>();
			for (String part : line.split("\t"))
			{
				int eq = part.indexOf('=');
				if (eq > 0)
				{
					f.put(part.substring(0, eq), part.substring(eq + 1));
				}
			}
			if (!"true".equals(f.get("complete")) || !"0".equals(f.get("plane")))
			{
				continue;
			}
			out.put(Integer.parseInt(f.get("region")), unhex(f.get("bits")));
		}
		return out;
	}

	// ---- bits ----

	private static boolean walkable(byte[] data, int rx, int ry)
	{
		int bit = (ry * REGION_SIZE + rx) * 2;
		return get(data, bit) || get(data, bit + 1);
	}

	private static boolean get(byte[] data, int bit)
	{
		int index = bit >> 3;
		return index < data.length && (data[index] >> (bit & 7) & 1) != 0;
	}

	private static byte[] unhex(String hex)
	{
		byte[] out = new byte[hex.length() / 2];
		for (int i = 0; i < out.length; i++)
		{
			out[i] = (byte) Integer.parseInt(hex.substring(i * 2, i * 2 + 2), 16);
		}
		return out;
	}

	private static byte[] readAll(InputStream in) throws IOException
	{
		ByteArrayOutputStream buf = new ByteArrayOutputStream();
		byte[] block = new byte[4096];
		int n;
		while ((n = in.read(block)) != -1)
		{
			buf.write(block, 0, n);
		}
		return buf.toByteArray();
	}

	private static void write(Map<Integer, byte[]> island, File file) throws IOException
	{
		try (DataOutputStream out = new DataOutputStream(new GZIPOutputStream(new FileOutputStream(file))))
		{
			out.writeInt(island.size());
			for (Map.Entry<Integer, byte[]> entry : island.entrySet())
			{
				out.writeInt(entry.getKey());
				out.writeInt(0);
				out.write(entry.getValue());
			}
		}
	}
}

import java.io.File;
import net.runelite.cache.region.Region;
import net.runelite.cache.region.RegionLoader;

/**
 * Renders the island's terrain as text, to find out how much of a walkability map
 * can be built without XTEA keys.
 *
 * <p>Object locations for the Wyrmscraig regions are encrypted and the local key file
 * predates the content, so the objects that block movement — walls, rocks, buildings —
 * cannot be read offline. Terrain can: map archives are not encrypted.
 *
 * <p>What this establishes is whether terrain alone is worth shipping as a baseline.
 * If the land/sea boundary is legible then golems can be given the whole island to
 * roam from the first login, with real collision refining it wherever the player
 * actually walks. If it is not, the map has to be harvested in game and there is no
 * shortcut.
 */
public class TerrainProbe
{
	private static final int[] REGIONS = {10274, 10275, 10018, 10019};

	public static void main(String[] args) throws Exception
	{
		File cacheDir = new File(args.length > 0
			? args[0]
			: System.getProperty("user.home") + "/.runelite/jagexcache/oldschool/LIVE");

		try (net.runelite.cache.fs.Store store = new net.runelite.cache.fs.Store(cacheDir))
		{
			store.load();

			RegionLoader loader = new RegionLoader(store, regionId -> new int[4]);
			loader.loadRegions();

			for (int wanted : REGIONS)
			{
				Region region = null;
				for (Region r : loader.getRegions())
				{
					if (r.getRegionID() == wanted)
					{
						region = r;
						break;
					}
				}

				if (region == null)
				{
					System.out.println("region " + wanted + ": not in cache");
					continue;
				}

				render(region);
			}
		}
	}

	/**
	 * One character per tile, north at the top.
	 *
	 * <p>'#' blocked terrain, '~' water (an overlay the engine will not let you walk
	 * on), '.' open ground, ' ' nothing authored at all — which is what open sea and
	 * unbuilt space look like.
	 */
	private static void render(Region region)
	{
		System.out.println();
		System.out.println("=== region " + region.getRegionID()
			+ "  base (" + region.getBaseX() + "," + region.getBaseY() + ") plane 0 ===");

		int blocked = 0, water = 0, open = 0, empty = 0;

		for (int y = Region.Y - 1; y >= 0; y--)
		{
			StringBuilder row = new StringBuilder();
			for (int x = 0; x < Region.X; x++)
			{
				int setting = region.getTileSetting(0, x, y);
				int overlay = region.getOverlayId(0, x, y);
				int underlay = region.getUnderlayId(0, x, y);

				char c;
				if ((setting & 1) != 0)
				{
					c = '#';
					blocked++;
				}
				else if (overlay == 0 && underlay == 0)
				{
					c = ' ';
					empty++;
				}
				else if (isWaterOverlay(overlay))
				{
					c = '~';
					water++;
				}
				else
				{
					c = '.';
					open++;
				}
				row.append(c);
			}
			System.out.println(row);
		}

		System.out.printf("blocked=%d water=%d open=%d empty=%d%n", blocked, water, open, empty);
	}

	/**
	 * Overlay IDs the game paints water with. Not exhaustive — this is a probe, and
	 * the point is only to see whether a coastline shows up at all.
	 */
	private static boolean isWaterOverlay(int overlay)
	{
		return overlay == 6 || overlay == 7 || overlay == 15 || overlay == 22
			|| overlay == 54 || overlay == 55 || overlay == 71 || overlay == 72;
	}
}

package com.golemsdontdie;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;

/**
 * Rebuilds a golem's model from the cache, unposed.
 *
 * <p>The tempting shortcut is to take {@link net.runelite.api.Renderable#getModel()}
 * off the live NPC, the way the Player Owned Island plugin copies the player. That
 * works for a copy that only has to live as long as the thing it is copying, and
 * only if the original keeps supplying fresh frames — the model handed back is
 * already posed for the current animation frame, and the client owns the buffer it
 * sits in.
 *
 * <p>Neither holds here. The copy has to outlive the golem by an unbounded amount
 * and animate on its own, so it needs the <i>rest</i> pose the animation frames are
 * defined against. Posing a posed model compounds the two transforms and produces a
 * golem folded through itself.
 *
 * <p>So the model is assembled the way the client would: load each model ID from the
 * composition, apply the composition's colour swaps, merge, scale, and light. What
 * comes back is a rest-pose {@link Model} that
 * {@link Client#applyTransformations(Model, net.runelite.api.Animation, int, net.runelite.api.Animation, int)}
 * will accept for as long as the plugin cares to keep it.
 */
@Slf4j
@Singleton
class GolemModelFactory
{
	/**
	 * The client's base lighting for actors. An NPC's own ambient and contrast are
	 * added to these — a detail that is easy to miss and plainly visible when missed,
	 * since a copy lit with the bare defaults sits next to the real thing looking
	 * flatter and the wrong brightness.
	 */
	private static final int BASE_AMBIENT = 64;
	private static final int BASE_CONTRAST = 850;
	private static final int LIGHT_X = -30;
	private static final int LIGHT_Y = -50;
	private static final int LIGHT_Z = -30;

	/** Composition scales are in 128ths; 128 means "as authored". */
	private static final int UNSCALED = 128;

	@Inject
	private Client client;

	/**
	 * One built model per NPC ID, shared by every golem wearing it.
	 *
	 * <p>Every golem on the island is the same NPC with the same models, recolours and
	 * scale, so building one per golem was building the same thing hundreds of times —
	 * a cache load, a merge, a vertex clone and a lighting pass each. With a few
	 * hundred golems arriving at once as the scene loads, that is seconds of stall for
	 * no benefit.
	 *
	 * <p>Sharing is safe because nothing downstream writes to the base model:
	 * {@link Client#applyTransformations} clones the vertices out of its source and
	 * leaves it untouched, and the posed result it returns is what gets drawn.
	 */
	private final Map<Integer, Model> cache = new HashMap<>();

	/**
	 * The rest-pose model for a snapshot, built once and thereafter shared.
	 *
	 * @return the lit model, or null if the cache would not give up the parts
	 */
	Model modelFor(GolemSnapshot snapshot)
	{
		Model cached = cache.get(snapshot.getNpcId());
		if (cached != null)
		{
			return cached;
		}

		Model built = build(snapshot);
		if (built != null)
		{
			cache.put(snapshot.getNpcId(), built);
		}
		return built;
	}

	/**
	 * Animation definitions, shared the same way the models are.
	 *
	 * <p>Golems switch between walking and standing constantly, and each switch used to
	 * re-fetch the definition from the client. There are exactly two of them across the
	 * whole population, and an {@link Animation} is immutable frame data — the mutable
	 * playback state lives in each golem's own controller — so one copy of each serves
	 * every golem on the island.
	 */
	private final Map<Integer, Animation> animations = new HashMap<>();

	/** The animation for an ID, loaded once. Null for -1, or if the cache lacks it. */
	Animation animationFor(int animationId)
	{
		if (animationId == -1)
		{
			return null;
		}
		// computeIfAbsent is avoided: loadAnimation can return null, and that would
		// mean re-asking for a missing animation on every switch.
		if (animations.containsKey(animationId))
		{
			return animations.get(animationId);
		}
		Animation loaded = client.loadAnimation(animationId);
		animations.put(animationId, loaded);
		return loaded;
	}

	/**
	 * Drops the shared models and animations. Called when the plugin stops, so a
	 * disable/enable cycle does not keep handing out resources built against a client
	 * that has moved on.
	 */
	void clear()
	{
		cache.clear();
		animations.clear();
	}

	/**
	 * Builds the rest-pose model described by a snapshot.
	 *
	 * @return the lit model, or null if the cache would not give up the parts
	 */
	private Model build(GolemSnapshot snapshot)
	{
		try
		{
			int[] ids = snapshot.getModelIds();
			ModelData[] parts = new ModelData[ids.length];
			int found = 0;

			for (int id : ids)
			{
				ModelData part = client.loadModelData(id);
				if (part == null)
				{
					// A single missing part would leave a golem with no head. Better to
					// fail the whole build and let the real death play out.
					log.debug("Golem model part {} not in cache for npc {}", id, snapshot.getNpcId());
					return null;
				}
				parts[found++] = part;
			}

			if (found == 0)
			{
				return null;
			}

			ModelData merged = client.mergeModels(parts, found);
			if (merged == null)
			{
				return null;
			}

			// Recolour and resize both write into the vertex and colour arrays, which
			// are shared with the cache's copy until cloned. Skipping this repaints
			// every other model in the game that happens to share the source.
			merged.cloneColors().cloneVertices();

			short[] from = snapshot.getRecolourFrom();
			short[] to = snapshot.getRecolourTo();
			for (int i = 0; i < Math.min(from.length, to.length); i++)
			{
				merged.recolor(from[i], to[i]);
			}

			int width = snapshot.getWidthScale() <= 0 ? UNSCALED : snapshot.getWidthScale();
			int height = snapshot.getHeightScale() <= 0 ? UNSCALED : snapshot.getHeightScale();
			if (width != UNSCALED || height != UNSCALED)
			{
				// Y is the vertical axis, and it is the one the height scale drives.
				merged.scale(width, height, width);
			}

			Model model = merged.light(
				BASE_AMBIENT + GolemContent.GOLEM_AMBIENT,
				BASE_CONTRAST + GolemContent.GOLEM_CONTRAST,
				LIGHT_X, LIGHT_Y, LIGHT_Z);
			if (model == null)
			{
				return null;
			}
			model.calculateBoundsCylinder();
			return model;
		}
		catch (RuntimeException e)
		{
			log.debug("Could not build golem model for npc {}", snapshot.getNpcId(), e);
			return null;
		}
	}
}

package com.golemsdontdie;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Random;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/**
 * One golem, simulated in world coordinates whether or not it is on screen.
 *
 * <p>The separation is the point. A golem is a position, a heading and an intention;
 * drawing it is a view onto that, attached only while it happens to be inside the
 * loaded scene. So a golem that wanders off the edge of the scene keeps walking, and
 * wanders back on later, instead of the plugin having to decide what to do about the
 * edge of the world.
 *
 * <p>Positions are integer 128ths of a tile — the same unit the client's local
 * coordinates use. Floats would accumulate error over a golem that walks for hours,
 * and there is nothing here that fractions of a 128th would buy.
 */
class Golem
{
	/** 128 units of position per tile, matching {@link net.runelite.api.coords.LocalPoint}. */
	static final int TILE = 128;

	/** Client cycles (20ms) per tile walked. One game tick, i.e. normal NPC walking pace. */
	private static final int CYCLES_PER_TILE = 30;

	/** Orientation units turned per cycle. 2048 is a full circle. */
	private static final int TURN_PER_CYCLE = 24;

	/** Angle units: 0 south, 512 west, 1024 north, 1536 east. */
	private static final int SOUTH = 0, WEST = 512, NORTH = 1024, EAST = 1536;

	/** Cycles a golem stands still between walks, before and after a random spread. */
	private static final int DWELL_MIN = 20;
	private static final int DWELL_SPREAD = 130;

	@Getter
	private final GolemSnapshot snapshot;

	/** Where it was made. The penned roam area is measured from here. */
	@Getter
	private final WorldPoint home;

	@Getter
	private final int plane;

	/**
	 * Seeded per golem so that two golems made on the same tile do not walk in
	 * lockstep, and so a restored golem carries on with its own gait.
	 */
	private final Random random;

	/** Position in 128ths of a tile, world-absolute. */
	@Getter
	private int fineX;
	@Getter
	private int fineY;

	@Getter
	private int orientation;
	private int targetOrientation;

	/** Remaining tiles of the current walk, as world tile pairs. */
	private final Deque<int[]> path = new ArrayDeque<>();

	/** The step in progress, interpolated between two tile centres. */
	private int stepFromX, stepFromY, stepToX, stepToY;
	private int stepElapsed;
	private boolean stepping;

	/** Cycles left standing still before choosing somewhere new to go. */
	private int dwellRemaining;

	/** Whether this golem used a path search on the current frame. */
	private boolean searched;

	/**
	 * Cycles left of the crumble, or -1 if this golem is not dying.
	 *
	 * <p>A golem being retired plays the game's own death animation before it goes.
	 * Vanishing on the spot would look like a bug — and since the whole plugin exists
	 * to stop golems disappearing, one that disappears anyway should at least do it
	 * the way the game does.
	 */
	private int dyingCycles = -1;

	/** True once the crumble has been started. The golem stops walking and cannot path. */
	boolean isDying()
	{
		return dyingCycles >= 0;
	}

	/** True when the crumble has played out and the golem should be dropped. */
	boolean isCrumbled()
	{
		return dyingCycles == 0;
	}

	/**
	 * Begins the crumble. Idempotent, so asking twice does not restart it.
	 */
	void startDying()
	{
		if (dyingCycles < 0)
		{
			dyingCycles = GolemContent.GOLEM_DEATH_CYCLES;
			path.clear();
			stepping = false;
			walking = false;
		}
	}

	/** True while the golem is moving, which selects the walk animation over the idle. */
	@Getter
	private boolean walking;

	/** Set when the golem is inside the loaded scene and should be drawn. */
	@Getter
	@Setter
	private FakeGolem renderer;

	/**
	 * A name the player has given this golem, or null for none.
	 *
	 * <p>Bookkeeping for the side panel only. It is deliberately not used as the
	 * hover target: the world calls every one of them "Golem", and a nickname
	 * appearing on right-click would give the copy away.
	 */
	@Getter
	@Setter
	private String nickname;

	/** Stable identity for the side panel and the save file, assigned on creation. */
	@Getter
	private final long id;

	Golem(GolemSnapshot snapshot, WorldPoint home, long seed, int startFineX, int startFineY)
	{
		this.snapshot = snapshot;
		this.home = home;
		this.plane = home.getPlane();
		this.random = new Random(seed);
		this.id = seed;

		this.fineX = startFineX;
		this.fineY = startFineY;
		this.orientation = snapshot.getOrientation() & 2047;
		this.targetOrientation = this.orientation;
		this.dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
	}

	/**
	 * Creates a golem standing on the centre of a tile.
	 *
	 * <p>Used when restoring a save, where only the tile was written down. Taking over
	 * from a live golem uses the other constructor with its exact sub-tile position —
	 * snapping to a tile centre there is precisely what made the first version look
	 * like the copy teleported.
	 */
	static Golem onTile(GolemSnapshot snapshot, WorldPoint home, long seed, WorldPoint at)
	{
		return new Golem(snapshot, home, seed,
			at.getX() * TILE + TILE / 2,
			at.getY() * TILE + TILE / 2);
	}

	/**
	 * True if a scene-local position is inside the loaded scene.
	 *
	 * <p>Replaces {@link net.runelite.api.coords.LocalPoint#isInScene()}, which is
	 * deprecated because it assumes every scene is the classic 104 tiles square.
	 * Asking the world view for its own size is correct for instances and for
	 * whatever sizes the client grows to support later.
	 */
	static boolean isInScene(WorldView wv, int localX, int localY)
	{
		return localX >= 0 && localY >= 0
			&& localX < wv.getSizeX() * TILE
			&& localY < wv.getSizeY() * TILE;
	}

	/** The tile the golem is standing on or walking out of. */
	WorldPoint currentTile()
	{
		return new WorldPoint(fineX / TILE, fineY / TILE, plane);
	}

	/**
	 * Advances the simulation.
	 *
	 * @param cycles client cycles (20ms each) since the last advance
	 * @param bounds where it may walk, re-derived each time so that flipping the free
	 *               roam setting takes effect on the golem's next decision
	 */
	boolean advance(int cycles, IslandMemory memory, GolemPathfinder pathfinder, boolean mayPath)
	{
		if (cycles <= 0)
		{
			return false;
		}
		this.searched = false;

		if (isDying())
		{
			// Stands where it is and crumbles. No turning, no walking, no pathing.
			dyingCycles = Math.max(0, dyingCycles - cycles);
			return false;
		}

		turnToward(cycles);

		// Movement is resolved a step at a time rather than by advancing a distance,
		// so a large `cycles` — after a stutter, or a tab-out — carries the golem
		// through several whole tiles instead of teleporting it past a wall.
		int remaining = cycles;
		while (remaining > 0)
		{
			if (!stepping)
			{
				if (path.isEmpty())
				{
					walking = false;
					dwellRemaining -= remaining;
					if (dwellRemaining > 0)
					{
						return searched;
					}
					if (!mayPath)
					{
						// This frame's search budget is spent. Stand still and try again
						// next frame rather than joining a stampede of path searches.
						return searched;
					}
					// Overshoot is discarded: a golem that dawdled a few cycles too long
					// is not worth carrying an error forward for.
					remaining = 0;
					searched = true;
					chooseDestination(memory, pathfinder);
					if (path.isEmpty())
					{
						// Nowhere to go — usually a golem boxed in by scenery. Wait and
						// try again rather than spinning on it.
						dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
						return searched;
					}
					continue;
				}
				beginStep(path.poll());
			}

			int left = CYCLES_PER_TILE - stepElapsed;
			if (remaining < left)
			{
				stepElapsed += remaining;
				remaining = 0;
			}
			else
			{
				remaining -= left;
				stepElapsed = CYCLES_PER_TILE;
			}

			interpolateStep();

			if (stepElapsed >= CYCLES_PER_TILE)
			{
				stepping = false;
				if (path.isEmpty())
				{
					walking = false;
					dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
					return searched;
				}
			}
		}
		return searched;
	}

	private void beginStep(int[] tile)
	{
		stepFromX = fineX;
		stepFromY = fineY;
		stepToX = tile[0] * TILE + TILE / 2;
		stepToY = tile[1] * TILE + TILE / 2;
		stepElapsed = 0;
		stepping = true;
		walking = true;
		targetOrientation = headingFor(stepToX - stepFromX, stepToY - stepFromY);
	}

	private void interpolateStep()
	{
		fineX = stepFromX + (stepToX - stepFromX) * stepElapsed / CYCLES_PER_TILE;
		fineY = stepFromY + (stepToY - stepFromY) * stepElapsed / CYCLES_PER_TILE;
	}

	/**
	 * Picks somewhere new to walk.
	 *
	 * <p>The roam bounds are built here rather than passed in. They describe a window
	 * around wherever the golem currently is, so they are only meaningful at the moment
	 * of choosing — and building one per golem per frame, as the caller used to, meant
	 * hundreds of throwaway objects a frame to serve the handful of golems that were
	 * actually choosing anything.
	 */
	private void chooseDestination(IslandMemory memory, GolemPathfinder pathfinder)
	{
		int tileX = fineX / TILE;
		int tileY = fineY / TILE;
		path.clear();
		path.addAll(pathfinder.wanderPath(tileX, tileY, plane,
			new RoamBounds(memory, plane, tileX, tileY), random));
	}

	/** Eases the heading toward where the golem is walking, the short way round. */
	private void turnToward(int cycles)
	{
		if (orientation == targetOrientation)
		{
			return;
		}
		int delta = ((targetOrientation - orientation + 1024) & 2047) - 1024;
		int maxTurn = TURN_PER_CYCLE * cycles;
		if (Math.abs(delta) <= maxTurn)
		{
			orientation = targetOrientation;
		}
		else
		{
			orientation = (orientation + Integer.signum(delta) * maxTurn) & 2047;
		}
	}

	private static int headingFor(int dx, int dy)
	{
		if (Math.abs(dx) >= Math.abs(dy))
		{
			return dx >= 0 ? EAST : WEST;
		}
		return dy >= 0 ? NORTH : SOUTH;
	}

	/** The animation this golem should be playing right now. -1 if it has none. */
	int currentPoseAnimation()
	{
		if (isDying())
		{
			return GolemContent.GOLEM_DEATH_ANIMATION;
		}
		return walking ? snapshot.getWalkAnimation() : snapshot.getIdlePoseAnimation();
	}
}

package com.golemsdontdie;

/**
 * Golem Crafting identifiers, harvested once from the game cache and fixed here.
 *
 * <p>These were read out of the local OSRS cache with the tools in {@code dev-tools/}
 * rather than guessed or discovered at runtime. The cache is authoritative for all of
 * it, and {@code NpcDefinition} carries the walk and idle animation IDs that the
 * RuneLite client API does not expose on {@code NPCComposition} at all — so hardcoding
 * beats detection here, and does not cost a first-golem calibration.
 *
 * <p>Sources, for whoever has to re-derive these after a content update:
 * <ul>
 *   <li>NPC and animation IDs — {@code dev-tools/CacheRecon.java}</li>
 *   <li>Animation frame counts and durations — {@code dev-tools/RegionRecon.java}</li>
 *   <li>Island terrain and extent — {@code dev-tools/TerrainProbe.java}</li>
 * </ul>
 */
final class GolemContent
{
	private GolemContent()
	{
	}

	/**
	 * The wandering golem produced by the activity.
	 *
	 * <p>Size 1, unscaled, no recolours, and — tellingly — no right-click options at
	 * all, which is what a purely decorative NPC looks like. It sits in the same ID
	 * block as the Wyrmscraig Goat (16298–16302), which is how it was identified as
	 * this content's golem rather than one of the sixty-odd other golems in the game.
	 */
	static final int GOLEM_NPC_ID = 16304;

	/**
	 * Walking animation. 8 frames over 48 cycles — a brisk, heavy gait.
	 *
	 * <p>Used as the fallback when restoring a golem whose saved animation is missing.
	 * Normally the animations come off the live actor at handover and are written to
	 * the save, but a save written by an older version, or one that caught a golem
	 * mid-transition, can carry -1 — and a golem with no animation stands frozen.
	 */
	static final int GOLEM_WALK_ANIMATION = 14452;

	/** Standing animation. 12 frames over 225 cycles — a slow idle shift. */
	static final int GOLEM_IDLE_ANIMATION = 14453;

	/**
	 * The crumble. Confirmed in game: both golems in the dry run played it and then
	 * vanished, at ticks 423→429 and 534→540.
	 *
	 * <p>It is on no definition — a death is played by a script, not declared as a
	 * pose — so it was found by narrowing the sequences either side of the golem's own
	 * and then watching a real golem die.
	 *
	 * <p>The gap between the crumble starting and the NPC despawning is <b>6 game
	 * ticks</b>, about 3.6 seconds. That is the window the swap has to happen in, and
	 * it is generous: the plugin acts on the first frame.
	 */
	static final int GOLEM_DEATH_ANIMATION = 14455;

	/**
	 * How long the crumble runs, in client cycles. 18 frames over 90 cycles, read from
	 * the sequence definition and matching the 6 game ticks observed between a real
	 * golem starting to crumble and vanishing.
	 */
	static final int GOLEM_DEATH_CYCLES = 90;

	/**
	 * Played once as the golem steps off its plinth, 27 ticks before the crumble.
	 *
	 * <p>The handover trigger: the copy takes over on the tick this animation ends,
	 * which is the only moment a golem is reliably standing still.
	 */
	static final int GOLEM_SPAWN_ANIMATION = 14451;

	/**
	 * The examine text, confirmed in game.
	 *
	 * <p>The cache has none of this: NPC 16304 carries no ops of any kind and no
	 * params. It is flagged interactable, which is what makes the client offer Examine
	 * at all, but the string itself is server-side.
	 *
	 * <p>A real golem's menu is exactly "Walk here", "Examine", "Cancel" — no action
	 * option. The copies match that.
	 *
	 * @see GolemMenu
	 */
	static final String GOLEM_EXAMINE = "*cough* Golem. *cough* GOHLEM. *cough*";

	/**
	 * Lighting offsets from the NPC definition, applied on top of the client's
	 * defaults for actors.
	 *
	 * <p>Easy to miss and very visible: the client lights an NPC's model with
	 * {@code 64 + ambient} and {@code 850 + contrast}, so a copy lit with the bare
	 * defaults is subtly but consistently wrong next to the real thing — flatter, and
	 * the wrong brightness. These are the golem's own values.
	 */
	static final int GOLEM_AMBIENT = 10;
	static final int GOLEM_CONTRAST = 60;

	/** Wyrmscraig, from the world map element at (2600, 2240). */
	static final int WYRMSCRAIG_REGION = 10275;

	/**
	 * The plinth golems are made on, observed: every golem taken over so far recorded
	 * this as its home. Used as the spawn point when reviving golems the plugin never
	 * saw made.
	 */
	static final int PLINTH_X = 2596;
	static final int PLINTH_Y = 2256;

	/**
	 * The regions the bundled island map covers: (39..41, 34..36) around the site.
	 *
	 * <p>Taken from the Shortest Path world collision map, which is generated from the
	 * cache with XTEA keys this machine does not have, and cross-checked tile by tile
	 * against collision recorded live during the dry run — 95% agreement overall, 99.9%
	 * on the one region away from the crafting site. Shipping it is what lets golems
	 * roam ground the player has never walked.
	 */
	static final int[] ISLAND_REGIONS = {
		10018, 10019, 10020,
		10274, 10275, 10276,
		10530, 10531, 10532,
	};

	/** True if this NPC is the crafted golem. */
	static boolean isGolem(int npcId)
	{
		return npcId == GOLEM_NPC_ID;
	}

}

package com.golemsdontdie;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.image.BufferedImage;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the copies onto the minimap, the way a real golem is drawn.
 *
 * <p>The client puts a dot on the minimap for every NPC whose composition asks for
 * one, and the golem's does. A {@link net.runelite.api.RuneLiteObject} is not an NPC,
 * so it gets nothing — which left the real golems showing as yellow dots and the
 * copies beside them showing as bare minimap.
 *
 * <p>The dot is the game's own sprite, not an approximation of it. A hand-drawn square
 * is close enough to notice and not close enough to pass: the real dot is a shaded
 * circle, and two subtly different kinds of yellow dot on one minimap draw the eye
 * straight to the fake ones.
 *
 * <p>Drawing is clipped to the minimap widget so a golem at the edge slides under the
 * frame as a real one does, instead of being painted over it.
 */
class GolemMinimapOverlay extends Overlay
{
	/**
	 * Candidate minimap widgets, one per interface layout — fixed, the two resizable
	 * modes, and the stretched variant. Only one exists at a time; which one depends on
	 * settings this plugin has no business reading, so all four are tried.
	 */
	private static final int[] MINIMAP_WIDGETS = {
		InterfaceID.Toplevel.MINIMAP,
		InterfaceID.ToplevelOsrsStretch.MINIMAP,
		InterfaceID.ToplevelPreEoc.MINIMAP,
		InterfaceID.ToplevelOsm.MINIMAP,
	};

	/**
	 * How far the minimap reaches, in tiles, with a margin. Anything beyond this is
	 * rejected before the projection is attempted.
	 */
	private static final int MINIMAP_RANGE_TILES = 20;

	private final Client client;
	private final GolemsDontDiePlugin plugin;
	private final SpriteManager spriteManager;

	/** The game's yellow NPC dot, fetched once the sprite cache can supply it. */
	private BufferedImage dot;

	@Inject
	GolemMinimapOverlay(Client client, GolemsDontDiePlugin plugin, SpriteManager spriteManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.spriteManager = spriteManager;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<Golem> golems = plugin.activeGolems();
		if (golems.isEmpty())
		{
			return null;
		}

		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return null;
		}

		if (dot == null)
		{
			// Asked for lazily: the sprite cache is not necessarily ready when the
			// plugin starts, and a null here simply means trying again next frame.
			dot = spriteManager.getSprite(SpriteID.MapdotsInterface.YELLOW_NPC, 0);
			if (dot == null)
			{
				return null;
			}
		}

		Rectangle minimap = minimapBounds();
		if (minimap == null)
		{
			return null;
		}

		// The minimap only reaches a short way, so a golem further out than that cannot
		// produce a dot however the projection is done. Rejecting on tile distance
		// first is two subtractions against a matrix transform, which matters when the
		// island holds hundreds of golems and this runs every frame.
		Player me = client.getLocalPlayer();
		if (me == null || me.getWorldLocation() == null)
		{
			return null;
		}
		int playerX = me.getWorldLocation().getX();
		int playerY = me.getWorldLocation().getY();

		Shape original = graphics.getClip();
		graphics.setClip(minimap);
		try
		{
			for (Golem golem : golems)
			{
				// Only golems actually being drawn in the scene. One that has wandered
				// out of it is off the minimap anyway, and its local coordinates would
				// be meaningless.
				if (golem.getRenderer() == null || golem.getPlane() != wv.getPlane())
				{
					continue;
				}

				if (Math.abs(golem.getFineX() / Golem.TILE - playerX) > MINIMAP_RANGE_TILES
					|| Math.abs(golem.getFineY() / Golem.TILE - playerY) > MINIMAP_RANGE_TILES)
				{
					continue;
				}

				int localX = golem.getFineX() - wv.getBaseX() * Golem.TILE;
				int localY = golem.getFineY() - wv.getBaseY() * Golem.TILE;
				if (!Golem.isInScene(wv, localX, localY))
				{
					continue;
				}

				Point at = Perspective.localToMinimap(client, new LocalPoint(localX, localY, wv));
				if (at == null)
				{
					continue;
				}

				// Centred on the point, matching how the client places its own dots.
				graphics.drawImage(dot,
					at.getX() - dot.getWidth() / 2,
					at.getY() - dot.getHeight() / 2,
					null);
			}
		}
		finally
		{
			graphics.setClip(original);
		}

		return null;
	}

	/**
	 * The on-screen rectangle of whichever minimap widget is currently live.
	 *
	 * @return the bounds, or null if no minimap is showing
	 */
	private Rectangle minimapBounds()
	{
		for (int id : MINIMAP_WIDGETS)
		{
			Widget widget = client.getWidget(id);
			if (widget != null && !widget.isHidden())
			{
				return widget.getBounds();
			}
		}
		return null;
	}
}

package com.golemsdontdie;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(GolemsDontDieConfig.GROUP)
public interface GolemsDontDieConfig extends Config
{
	String GROUP = "golemsdontdie";

	/** Key for the serialised golem roster. Plugin-written, so not a {@link ConfigItem}. */
	String SAVED_GOLEMS_KEY = "savedGolems";

	@ConfigSection(
		name = "Golems",
		description = "How many golems to keep",
		position = 0
	)
	String golemsSection = "golems";

	// Roaming and persistence are not settings. Golems always roam the whole island and
	// are always kept permanently — those were the interesting options and the answer
	// turned out to be the same in both cases, so offering the alternatives only
	// invited someone to pick the worse one.

	@ConfigItem(
		keyName = "limitGolems",
		name = "Limit golems",
		description = "Cap golems to improve performance if too many spawn",
		section = golemsSection,
		position = 0
	)
	default boolean limitGolems()
	{
		return false;
	}

	@ConfigItem(
		keyName = "maxGolems",
		name = "Maximum golems",
		description = "Maximum golems present on island. Has no effect if Limit golems is off.",
		section = golemsSection,
		position = 1
	)
	@Range(min = 1, max = 200)
	default int maxGolems()
	{
		return 25;
	}
}

package com.golemsdontdie;

import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.coords.WorldPoint;

/**
 * Everything about a live golem that a copy will need, recorded while the real one
 * is still standing.
 *
 * <p>It has to be gathered in advance because none of it survives the NPC. Once the
 * golem despawns it is gone from the scene and the animation IDs the client was
 * posing it with go with it — so the plugin keeps a snapshot refreshed for every
 * golem it is watching, and builds the copy from the last one taken before the death
 * animation began.
 *
 * <p>The split between what is looked up and what is remembered matters for saving.
 * Models, recolours, scale and size all come from {@link NPCComposition}, so they can
 * be re-fetched from the cache later given only an NPC ID. The animation IDs cannot:
 * the RuneLite API's composition exposes no standing or walking animation, so there
 * is no way to ask the cache how an NPC walks. Only the live
 * {@link net.runelite.api.Actor}, which has already been told, will answer — which is
 * why those three ints are the part that has to be written to disk.
 */
@Value
class GolemSnapshot
{
	int npcId;
	String name;

	/** Model IDs from the composition, merged and recoloured to build the base model. */
	int[] modelIds;
	short[] recolourFrom;
	short[] recolourTo;

	/** Composition scaling, in 128ths. 128 = as authored. */
	int widthScale;
	int heightScale;

	/** Footprint in tiles, used to size the drawn object's tile-sorting radius. */
	int size;

	/** Pose animations, harvested from the actor. -1 where the golem has none. */
	int idlePoseAnimation;
	int walkAnimation;
	int runAnimation;

	/** Where it stood and which way it faced when the snapshot was taken. */
	WorldPoint worldLocation;
	int orientation;

	/** A copy of this snapshot facing somewhere else. */
	GolemSnapshot facing(int newOrientation)
	{
		return new GolemSnapshot(npcId, name, modelIds, recolourFrom, recolourTo,
			widthScale, heightScale, size, idlePoseAnimation, walkAnimation, runAnimation,
			worldLocation, newOrientation & 2047);
	}

	/**
	 * Reads the current state of a live golem.
	 *
	 * @return the snapshot, or null if the NPC has no usable composition
	 */
	static GolemSnapshot of(NPC npc)
	{
		NPCComposition comp = npc.getTransformedComposition();
		if (comp == null)
		{
			comp = npc.getComposition();
		}
		if (comp == null)
		{
			return null;
		}

		return build(
			comp,
			npc.getName() == null ? comp.getName() : npc.getName(),
			npc.getIdlePoseAnimation(),
			npc.getWalkAnimation(),
			npc.getRunAnimation(),
			npc.getWorldLocation(),
			npc.getCurrentOrientation());
	}

	/**
	 * Rebuilds a snapshot for a saved golem, taking appearance from the cache and
	 * everything the cache does not hold from the save.
	 *
	 * @return the snapshot, or null if the NPC ID is no longer in the cache
	 */
	static GolemSnapshot restore(Client client, int npcId, int idlePose, int walk, int run,
		WorldPoint where, int orientation)
	{
		NPCComposition comp = client.getNpcDefinition(npcId);
		if (comp == null)
		{
			return null;
		}

		// A golem with no animation stands frozen, which is worse than one moving
		// slightly wrong. Saves written before the animations were recorded, or ones
		// that caught a golem mid-transition, can carry -1 — so fall back to the known
		// values rather than restoring a statue.
		if (walk == -1)
		{
			walk = GolemContent.GOLEM_WALK_ANIMATION;
		}
		if (idlePose == -1)
		{
			idlePose = GolemContent.GOLEM_IDLE_ANIMATION;
		}

		return build(comp, comp.getName(), idlePose, walk, run, where, orientation);
	}

	private static GolemSnapshot build(NPCComposition comp, String name, int idlePose, int walk, int run,
		WorldPoint where, int orientation)
	{
		int[] models = comp.getModels();
		if (models == null || models.length == 0)
		{
			return null;
		}

		return new GolemSnapshot(
			comp.getId(),
			name == null ? "Golem" : name,
			models.clone(),
			comp.getColorToReplace() == null ? new short[0] : comp.getColorToReplace().clone(),
			comp.getColorToReplaceWith() == null ? new short[0] : comp.getColorToReplaceWith().clone(),
			comp.getWidthScale(),
			comp.getHeightScale(),
			Math.max(1, comp.getSize()),
			idlePose,
			walk,
			run,
			where,
			orientation & 2047);
	}
}

package com.golemsdontdie;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Singleton;
import net.runelite.api.NPC;

/**
 * Decides what counts as a golem, and when one is dying.
 *
 * <p>Both answers are hardcoded from {@link GolemContent}, harvested once out of the
 * game cache rather than discovered at runtime. That is worth doing rather than
 * clever: a name match would sweep up the sixty-odd unrelated golems in the game, and
 * learning the death animation from the first golem to die costs one visible crumble
 * every time the roster is empty. Knowing the IDs up front means the very first swap
 * is as seamless as the hundredth.
 *
 * <p>Both remain overridable, because a content update can move them and a config
 * field is faster than a rebuild.
 */
@Singleton
class GolemDetector
{
	/** Live golems being watched, by NPC index, with their most recent snapshot. */
	private final Map<Integer, GolemSnapshot> tracked = new HashMap<>();

	/** Golems already replaced by a copy, so a despawn does not replace them twice. */
	private final Set<Integer> replaced = new HashSet<>();

	/**
	 * Golems seen playing the plinth animation. The copy takes over on the tick that
	 * animation ends, which is the one moment a golem is reliably standing still.
	 */
	private final Set<Integer> leftPlinth = new HashSet<>();

	// ---- identity ----

	/** True if this NPC is a crafted golem. */
	boolean isGolem(NPC npc)
	{
		return npc != null && GolemContent.isGolem(npc.getId());
	}

	/** True if this animation is the crumble. */
	boolean isDeathAnimation(int animationId)
	{
		return animationId != -1 && animationId == GolemContent.GOLEM_DEATH_ANIMATION;
	}

	// ---- tracking ----

	/** Records or refreshes what a live golem looks like. */
	void track(NPC npc)
	{
		GolemSnapshot snapshot = GolemSnapshot.of(npc);
		if (snapshot != null)
		{
			tracked.put(npc.getIndex(), snapshot);
		}
	}

	/** The last snapshot taken of a golem, or null if it was never tracked. */
	GolemSnapshot snapshotOf(NPC npc)
	{
		return tracked.get(npc.getIndex());
	}

	/** Records that a golem has played the animation for stepping off its plinth. */
	void noteLeftPlinth(NPC npc)
	{
		leftPlinth.add(npc.getIndex());
	}

	/** True if this golem has stepped off its plinth and is now standing free. */
	boolean hasLeftPlinth(NPC npc)
	{
		return leftPlinth.contains(npc.getIndex());
	}

	/** Marks a golem as already replaced, so its despawn is ignored. */
	void markReplaced(NPC npc)
	{
		replaced.add(npc.getIndex());
	}

	boolean wasReplaced(NPC npc)
	{
		return replaced.contains(npc.getIndex());
	}

	/** Drops all state for an NPC that has left the scene. */
	void forget(NPC npc)
	{
		tracked.remove(npc.getIndex());
		replaced.remove(npc.getIndex());
		leftPlinth.remove(npc.getIndex());
	}

	/** Drops everything. Called on logout and when the plugin stops. */
	void reset()
	{
		tracked.clear();
		replaced.clear();
		leftPlinth.clear();
	}
}

package com.golemsdontdie;

import java.util.Random;

/**
 * The area a golem is allowed to wander: everywhere the island map says is walkable.
 *
 * <p>There used to be a second, penned shape that kept golems within a few tiles of
 * the plinth they were made on. It is gone. Free roam turned out to be the only
 * version worth having, and keeping the alternative around only offered a way to make
 * the plugin worse.
 *
 * <p>No outer edge is needed. {@link IslandMemory} only knows about the island, so
 * asking it whether a tile is walkable is already asking whether the tile is on the
 * island — a golem cannot wander into the sea because the map has nothing to say
 * about the sea.
 */
class RoamBounds
{
	/**
	 * How far a golem looks for its next destination, in tiles.
	 *
	 * <p>Sampling from the whole island instead would have golems repeatedly setting
	 * off on island-long treks, which both reads wrong — a golem is a wandering lump,
	 * not a commuter — and makes every path search run to its node budget. A window
	 * around the golem gives the same eventual coverage through a random walk at a
	 * fraction of the cost.
	 */
	private static final int WANDER_WINDOW = 12;

	private final IslandMemory memory;
	private final int plane;
	private final int centreX;
	private final int centreY;

	RoamBounds(IslandMemory memory, int plane, int centreX, int centreY)
	{
		this.memory = memory;
		this.plane = plane;
		this.centreX = centreX;
		this.centreY = centreY;
	}

	/** True if a golem may enter this world tile. */
	boolean contains(int worldX, int worldY)
	{
		return memory.isKnownWalkable(worldX, worldY, plane);
	}

	/** A candidate destination. May be unwalkable — the caller rejects and retries. */
	int[] sample(Random random)
	{
		return new int[]{
			centreX - WANDER_WINDOW + random.nextInt(WANDER_WINDOW * 2 + 1),
			centreY - WANDER_WINDOW + random.nextInt(WANDER_WINDOW * 2 + 1),
		};
	}
}

package com.golemsdontdie;

import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.RuneLiteObjectController;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/**
 * Draws a {@link Golem} while it is inside the loaded scene.
 *
 * <p>This is deliberately thin: it owns no intentions and decides nothing about
 * where the golem goes. It reads the simulation's position each frame and poses the
 * model to match. A golem that leaves the scene loses its renderer and keeps walking;
 * one that comes back gets a new one.
 *
 * <p>The pose is applied here rather than borrowed from a real NPC. Copying a posed
 * model — the trick the Player Owned Island plugin uses for the player — needs an
 * original that is still alive and still being posed every frame. There isn't one:
 * the golem this stands in for is dead. So the base model is the cache's rest pose
 * and the animation is driven from an {@link AnimationController} of our own, which
 * is also what lets a golem keep walking indefinitely rather than for as long as
 * something else animates it.
 */
class FakeGolem extends RuneLiteObjectController
{
	/** 128ths of a tile per tile, for scene-to-local conversion. */
	private static final int TILE = Golem.TILE;

	private final Client client;
	private final Golem golem;
	private final Model baseModel;

	/** Source of the shared model and animation definitions. */
	private final GolemModelFactory shared;

	/**
	 * Drives the walk or idle loop. A single controller rather than the client's
	 * active-plus-pose pair, because a wandering golem only ever plays one thing at
	 * a time — there is no attack or emote to layer over the gait.
	 */
	private final AnimationController animation;

	/** Which animation ID the controller currently holds, to avoid resetting it every frame. */
	private int loadedAnimationId = Integer.MIN_VALUE;

	FakeGolem(Client client, Golem golem, Model baseModel, GolemModelFactory shared)
	{
		this.client = client;
		this.golem = golem;
		this.baseModel = baseModel;
		this.shared = shared;
		this.animation = new AnimationController(client, -1);

		// A single-tile object is drawn correctly by the default radius; a bigger
		// golem needs the tiles under its footprint drawn first or it will z-fight
		// with the ground at its edges.
		int size = Math.max(1, golem.getSnapshot().getSize());
		setRadius(size * 64 - 4);
		setDrawFrontTilesFirst(true);

		syncTransform();
		applyPose();
	}

	/**
	 * Called by the client once per frame while registered.
	 *
	 * <p>Only the animation is advanced here. Position is advanced centrally by the
	 * plugin, for every golem including the ones off screen — if movement happened
	 * here, a golem would freeze the moment it left the scene and never walk back in.
	 */
	@Override
	public void tick(int ticksSinceLastFrame)
	{
		syncTransform();
		applyPose();
		animation.tick(ticksSinceLastFrame);
	}

	@Override
	public Model getModel()
	{
		if (animation.getAnimation() == null)
		{
			return baseModel;
		}
		Model posed = animation.animate(baseModel);
		return posed == null ? baseModel : posed;
	}

	/**
	 * The shape the mouse has to be inside for this golem to be hovered.
	 *
	 * <p>A {@link RuneLiteObjectController} is drawn but not clickable — the client
	 * builds its menu from real entities, and a client-side object is not one. So the
	 * hit test has to be done by hand.
	 *
	 * <p>Tested against the <b>rest pose</b>, not the posed model. Using
	 * {@link #getModel()} here meant a full skeletal transform per golem per tick on
	 * top of projecting the geometry, which is what made the client stall whenever the
	 * cursor sat over the scene. It was also unsound: that model is a shared buffer the
	 * client reuses, and the API forbids holding it across another transformation —
	 * which is exactly what computing a clickbox from it does.
	 *
	 * <p>The cost of using the rest pose is that the box does not follow a swinging arm.
	 * For deciding whether the cursor is over a golem, that is not a cost worth paying
	 * a transform for.
	 *
	 * @return the clickbox, or null if it cannot be computed this frame
	 */
	java.awt.Shape clickbox()
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null || baseModel == null)
		{
			return null;
		}
		try
		{
			return Perspective.getClickbox(client, wv, baseModel, getOrientation(), getX(), getY(), getZ());
		}
		catch (RuntimeException e)
		{
			// Off-screen or degenerate geometry. Not being hoverable for a frame is
			// not worth propagating.
			return null;
		}
	}

	/** Copies the simulation's position and heading onto the drawn object. */
	private void syncTransform()
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return;
		}

		int localX = golem.getFineX() - wv.getBaseX() * TILE;
		int localY = golem.getFineY() - wv.getBaseY() * TILE;

		setX(localX);
		setY(localY);
		setWorldView(wv.getId());
		setLevel(golem.getPlane());
		setOrientation(golem.getOrientation());

		// Ground height has to be re-read as the golem moves, not just when it is
		// placed: Wyrmscraig is not flat, and a golem holding its spawn height would
		// sink into a rise and float off a dip.
		if (Golem.isInScene(wv, localX, localY))
		{
			setZ(Perspective.getTileHeight(client, new LocalPoint(localX, localY, wv), golem.getPlane()));
		}
	}

	/** Switches between the walk and idle loops as the simulation changes its mind. */
	private void applyPose()
	{
		int wanted = golem.currentPoseAnimation();
		if (wanted == loadedAnimationId && animation.getAnimation() != null)
		{
			return;
		}

		loadedAnimationId = wanted;
		animation.setAnimation(shared.animationFor(wanted));
	}
}

package com.golemsdontdie;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.Map;
import java.util.Random;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Picks somewhere for a golem to go, and works out how to walk there.
 *
 * <p>Everything is in world tiles, queried against {@link IslandMemory}, so a search
 * works the same whether the golem is on screen or three regions away. That is the
 * whole point of harvesting the map: pathing cannot depend on the scene, because
 * most golems will not be in it.
 *
 * <p>Paths are breadth-first over cardinal steps. A* would be the reflex, but the
 * distances are short — a golem picks a tile within its wander window, it does not
 * cross the island in one go — and BFS has the property that matters here: it is
 * exhaustive within its budget, so a golem penned in by scenery finds out it is
 * stuck rather than walking hopefully into a wall.
 */
@Singleton
class GolemPathfinder
{
	/**
	 * Ceiling on tiles visited per search. Reached only when a golem is walled in and
	 * the flood fill has to exhaust its pen before giving up — which is precisely the
	 * case worth bounding, because it recurs every time that golem picks a target.
	 */
	private static final int NODE_BUDGET = 3000;

	/** Tries for a reachable destination before the golem gives up and idles. */
	private static final int DESTINATION_ATTEMPTS = 10;

	private static final int[] DX = {1, -1, 0, 0};
	private static final int[] DY = {0, 0, 1, -1};

	@Inject
	private IslandMemory memory;

	/**
	 * A path to a random reachable destination inside {@code bounds}.
	 *
	 * <p>Destinations are sampled and rejected rather than enumerated. Enumerating
	 * every walkable tile would bias the choice toward whichever part of the area has
	 * the most of them; sampling keeps it even over the ground the player watches the
	 * golem cross.
	 *
	 * @return world tiles to walk through, excluding the start; empty if nowhere goes
	 */
	Deque<int[]> wanderPath(int startX, int startY, int plane, RoamBounds bounds, Random random)
	{
		for (int attempt = 0; attempt < DESTINATION_ATTEMPTS; attempt++)
		{
			int[] target = bounds.sample(random);
			if (target == null || (target[0] == startX && target[1] == startY))
			{
				continue;
			}
			if (!bounds.contains(target[0], target[1]) || !memory.isKnownWalkable(target[0], target[1], plane))
			{
				continue;
			}

			Deque<int[]> path = findPath(startX, startY, plane, target[0], target[1], bounds);
			if (!path.isEmpty())
			{
				return path;
			}
		}
		return new ArrayDeque<>();
	}

	/**
	 * Breadth-first path between two world tiles, staying inside {@code bounds}.
	 *
	 * @return the tiles to walk through, excluding the start; empty if unreachable
	 */
	Deque<int[]> findPath(int startX, int startY, int plane, int goalX, int goalY, RoamBounds bounds)
	{
		Deque<int[]> result = new ArrayDeque<>();
		if (startX == goalX && startY == goalY)
		{
			return result;
		}

		// Keyed by packed world tile rather than indexed by scene position: in free
		// roam the search is not confined to a scene, so there is no fixed-size grid
		// to index into.
		Map<Long, Long> cameFrom = new HashMap<>();
		Deque<Long> queue = new ArrayDeque<>();

		long start = pack(startX, startY);
		long goal = pack(goalX, goalY);
		cameFrom.put(start, start);
		queue.add(start);

		int visited = 0;
		boolean found = false;

		while (!queue.isEmpty() && visited < NODE_BUDGET)
		{
			long current = queue.poll();
			visited++;

			if (current == goal)
			{
				found = true;
				break;
			}

			int cx = unpackX(current);
			int cy = unpackY(current);

			for (int d = 0; d < DX.length; d++)
			{
				int nx = cx + DX[d];
				int ny = cy + DY[d];
				long next = pack(nx, ny);

				if (cameFrom.containsKey(next)
					|| !bounds.contains(nx, ny)
					|| !memory.canStep(cx, cy, plane, DX[d], DY[d]))
				{
					continue;
				}

				cameFrom.put(next, current);
				queue.add(next);
			}
		}

		if (!found)
		{
			return result;
		}

		// Walk the parent chain back, pushing each tile onto the front, which reverses
		// it into start-to-goal order.
		for (long at = goal; at != start; at = cameFrom.get(at))
		{
			result.addFirst(new int[]{unpackX(at), unpackY(at)});
		}
		return result;
	}

	private static long pack(int x, int y)
	{
		return ((long) x << 32) | (y & 0xFFFFFFFFL);
	}

	private static int unpackX(long packed)
	{
		return (int) (packed >> 32);
	}

	private static int unpackY(long packed)
	{
		return (int) packed;
	}
}

package com.golemsdontdie;

import java.awt.Shape;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/**
 * Gives the copies the right-click menu the real golems have.
 *
 * <p>Without this a fake golem is inert under the cursor: a
 * {@link net.runelite.api.RuneLiteObjectController} is drawn by the client but is not
 * an entity it will build a menu from, so hovering one produces nothing where the real
 * golem offered an option and an examine. That reads as wrong immediately — the
 * illusion survives the swap and then dies to a mouse hover.
 *
 * <p>So the hit test is done by hand each tick: take the posed model that was drawn,
 * ask {@link net.runelite.api.Perspective} for its clickbox, and see whether the mouse
 * is inside it. Entries are added with {@link MenuAction#RUNELITE} and their own click
 * handlers, so nothing is sent to the server — a fake golem is a local fiction and
 * clicking one must stay local.
 */
@Singleton
class GolemMenu
{
	/** Target colour the client uses for an NPC with no combat level. */
	private static final String NPC_COLOUR = "<col=ffff00>";

	@Inject
	private Client client;

	/**
	 * Adds entries for whichever golem is under the cursor.
	 *
	 * <p>Called once per client tick, which is when the client rebuilds its menu. Only
	 * the topmost golem gets entries — stacking three sets because three golems overlap
	 * is not what the real game does.
	 */
	void addEntries(List<Golem> golems)
	{
		if (client.isMenuOpen() || golems.isEmpty())
		{
			return;
		}

		Point mouse = client.getMouseCanvasPosition();
		if (mouse == null || mouse.getX() < 0 || mouse.getY() < 0)
		{
			return;
		}

		Golem hovered = topmostAt(golems, mouse);
		if (hovered == null)
		{
			return;
		}

		// A named golem is shown by its name.
		//
		// This does cost some of the disguise — every real golem is called "Golem", so
		// a named one is visibly not one of them. That is the right trade: naming a
		// golem you then cannot pick out of a crowd is pointless, and a name is only
		// ever there because the player deliberately put it there. Leave a golem
		// unnamed and it stays indistinguishable.
		String name = hovered.getNickname();
		if (name == null || name.isEmpty())
		{
			name = hovered.getSnapshot().getName();
		}
		String target = NPC_COLOUR + name + "</col>";

		// Index 1, immediately above Cancel, which the client always keeps at index 0.
		// The menu array is drawn bottom-up, so inserting at 0 would put Examine
		// *below* Cancel — which is exactly what the first attempt did, giving
		// "Walk here, Cancel, Examine" against the real "Walk here, Examine, Cancel".
		client.getMenu().createMenuEntry(1)
			.setOption("Examine")
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> message(GolemContent.GOLEM_EXAMINE));
	}

	/**
	 * How far from the cursor, in pixels, a golem's ground point can be and still be
	 * worth an exact hit test. Generous enough to cover a golem drawn tall on screen
	 * with the camera zoomed right in.
	 */
	private static final int CANDIDATE_RADIUS = 180;

	/**
	 * Ceiling on exact hit tests per tick. Only reached when the cursor sits over a
	 * heap of golems that are near it but not under it, which is the one case the
	 * early exit cannot help with.
	 */
	private static final int MAX_CLICKBOX_TESTS = 10;

	/** Lower on screen first — that is nearer the camera. */
	private static final Comparator<Candidate> BY_DEPTH =
		(a, b) -> Integer.compare(b.screenY, a.screenY);

	/** Reused between ticks so hovering the scene does not allocate every frame. */
	private final List<Candidate> candidates = new ArrayList<>();

	/**
	 * The golem whose clickbox contains the mouse and which is nearest the camera.
	 *
	 * <p>Nearest is approximated by the largest canvas Y of the clickbox — a golem
	 * drawn lower on the screen is closer to the camera in an isometric view, which is
	 * the same ordering the client's own entity picking produces.
	 *
	 * <p>Clickboxes are only computed for golems already near the cursor. Building one
	 * means projecting every face of the model and merging the results, and this runs
	 * on every client tick; doing it for a few hundred golems made the client stutter
	 * whenever the mouse was over the scene. Projecting a golem's ground point instead
	 * is a single matrix transform, so the expensive test is reserved for the handful
	 * of golems that could plausibly be under the cursor.
	 */
	private Golem topmostAt(List<Golem> golems, Point mouse)
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return null;
		}

		// Gather the golems near enough the cursor to be worth an exact test, keeping
		// how far down the screen each is drawn.
		candidates.clear();
		for (Golem golem : golems)
		{
			FakeGolem renderer = golem.getRenderer();
			if (renderer == null)
			{
				continue;
			}

			Point ground = Perspective.localToCanvas(client,
				new LocalPoint(renderer.getX(), renderer.getY(), wv), golem.getPlane());
			if (ground == null
				|| Math.abs(ground.getX() - mouse.getX()) > CANDIDATE_RADIUS
				|| Math.abs(ground.getY() - mouse.getY()) > CANDIDATE_RADIUS)
			{
				continue;
			}
			candidates.add(new Candidate(golem, ground.getY()));
		}

		// Nearest the camera first. In an isometric view a golem drawn lower on the
		// screen is in front, which is the order the client picks entities in — so the
		// first golem whose box contains the cursor is the answer and the rest need
		// never be projected at all. That early exit is what keeps this cheap when a
		// few hundred golems are piled up under the mouse; the radius filter alone
		// does nothing when they are all in the same place.
		candidates.sort(BY_DEPTH);

		int tested = 0;
		for (Candidate candidate : candidates)
		{
			if (tested++ >= MAX_CLICKBOX_TESTS)
			{
				// A pile deep enough to hit this is a pile where one more golem's
				// right-click is not worth a frame drop.
				break;
			}
			Shape clickbox = candidate.golem.getRenderer().clickbox();
			if (clickbox != null && clickbox.contains(mouse.getX(), mouse.getY()))
			{
				return candidate.golem;
			}
		}
		return null;
	}

	/** A golem near the cursor, with how far down the screen it is drawn. */
	private static final class Candidate
	{
		final Golem golem;
		final int screenY;

		Candidate(Golem golem, int screenY)
		{
			this.golem = golem;
			this.screenY = screenY;
		}
	}

	private void message(String text)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", text, null);
	}
}

package com.golemsdontdie;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.Base64;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.CollisionData;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.Constants;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/**
 * The plugin's memory of where a golem can walk on Wyrmscraig, in world
 * coordinates, learned by watching the scene and kept across logins.
 *
 * <p>Free roam needs passability for the whole island at once, and the scene only
 * ever holds the 104×104 tiles around the player. A golem three regions away has to
 * keep walking somewhere the client cannot currently be asked about. So the map is
 * harvested: every time a region loads, its collision flags are copied out and
 * folded into a world-space record that outlives the scene.
 *
 * <p>The storage is the two-bit-per-tile north/east scheme the Shortest Path plugin
 * uses, and that the Brainless Ourania plugin loads its bundled map with. South and
 * west are not stored because they are the north and east of the neighbouring tile;
 * halving the data for free matters when it has to fit in a config value.
 *
 * <p>Nothing is bundled. Wyrmscraig is new, so there is no prebuilt map to ship, and
 * a harvested one has the advantage of being right about the island as it actually
 * is rather than as it was when someone last exported it.
 */
@Slf4j
@Singleton
class IslandMemory
{
	/** Config key the serialised map is stored under. Plugin-written, so not a config item. */
	static final String MAP_KEY = "islandMap";

	/**
	 * The island map shipped with the plugin, covering the nine regions around the
	 * crafting site.
	 *
	 * <p>Built from the Shortest Path project's world collision map — generated from
	 * the game cache with XTEA keys, which the local cache's key file lacks for these
	 * regions — and cross-checked tile by tile against collision recorded live before
	 * being trusted. Without it, free roam could only cover ground the player had
	 * personally walked.
	 *
	 * @see #loadBundled()
	 */
	private static final String BUNDLED_MAP = "/island-map.gz";

	private static final int REGION_SIZE = 64;
	private static final int REGION_MASK = REGION_SIZE - 1;
	private static final int FLAGS_PER_TILE = 2;
	private static final int FLAG_NORTH = 0;
	private static final int FLAG_EAST = 1;
	private static final int BITS_PER_REGION = REGION_SIZE * REGION_SIZE * FLAGS_PER_TILE;
	private static final int WORDS_PER_REGION = BITS_PER_REGION / Long.SIZE;

	/** Blocked for standing on: an object, a wall filling the tile, or bad ground. */
	private static final int UNWALKABLE = CollisionDataFlag.BLOCK_MOVEMENT_FULL
		| CollisionDataFlag.BLOCK_MOVEMENT_OBJECT
		| CollisionDataFlag.BLOCK_MOVEMENT_FLOOR
		| CollisionDataFlag.BLOCK_MOVEMENT_FLOOR_DECORATION;

	/**
	 * Passability per region-and-plane. The key packs both so that a multi-level
	 * island does not collapse its floors onto each other.
	 */
	private final Map<Long, long[]> regions = new HashMap<>();

	/** Regions harvested this session, so a reload is not redone every scene change. */
	private final Set<Long> harvested = new HashSet<>();

	/**
	 * The region the first golem was seen in. Everything the island is taken to be
	 * is measured from here.
	 *
	 * <p>The alternative — hardcoding Wyrmscraig's region IDs — is not available:
	 * the content is newer than this plugin, and a wrong constant would silently
	 * disable free roam with no way for the player to tell why.
	 */
	@Getter
	private int anchorRegionId = -1;

	@Getter
	private boolean dirty = false;

	@Inject
	private Client client;

	// ---- the shipped baseline ----

	/**
	 * Loads the bundled island map, without disturbing anything already learned.
	 *
	 * <p>Merged rather than assigned, and merged <i>under</i> what is already there:
	 * a region harvested from a live scene reflects the island as it is right now,
	 * including objects that come and go, where the bundled map is a static export.
	 * Where both have an opinion the live one is kept.
	 *
	 * <p>Called at start-up, before the saved map is restored, so it acts as the floor
	 * that free roam stands on when the player has never been to Wyrmscraig.
	 */
	void loadBundled()
	{
		try (InputStream raw = IslandMemory.class.getResourceAsStream(BUNDLED_MAP))
		{
			if (raw == null)
			{
				log.warn("Bundled island map missing from the jar");
				return;
			}

			try (GZIPInputStream gz = new GZIPInputStream(raw);
				 java.io.DataInputStream data = new java.io.DataInputStream(gz))
			{
				int count = data.readInt();
				for (int i = 0; i < count; i++)
				{
					int regionId = data.readInt();
					int plane = data.readInt();
					byte[] packed = new byte[BITS_PER_REGION / 8];
					data.readFully(packed);

					long key = key(regionId, plane);
					if (regions.containsKey(key))
					{
						// Already known from a live scene, which is the better source.
						continue;
					}
					regions.put(key, toWords(packed));
				}

				if (anchorRegionId == -1)
				{
					anchorRegionId = GolemContent.WYRMSCRAIG_REGION;
				}
				log.debug("Loaded bundled island map: {} region-planes", count);
			}
		}
		catch (IOException | RuntimeException e)
		{
			// A missing or corrupt baseline is survivable — golems fall back to
			// roaming only what the player has walked.
			log.warn("Bundled island map unreadable", e);
		}
	}

	/** Repacks the bundled byte layout into the long words used at runtime. */
	private static long[] toWords(byte[] packed)
	{
		long[] words = new long[WORDS_PER_REGION];
		for (int i = 0; i < packed.length; i++)
		{
			words[i >> 3] |= (packed[i] & 0xFFL) << ((i & 7) * 8);
		}
		return words;
	}

	// ---- learning ----

	/**
	 * Records where the golems live, if it is not already known. Called the first
	 * time a golem is seen.
	 */
	void anchorAt(WorldPoint point)
	{
		if (anchorRegionId == -1)
		{
			anchorRegionId = point.getRegionID();
			dirty = true;
			log.debug("Island anchored at region {}", anchorRegionId);
		}
	}

	/**
	 * True once there is an anchor. With the bundled map loaded this is true from
	 * start-up, so golems can roam before the player has ever seen one made.
	 */
	boolean hasAnchor()
	{
		return anchorRegionId != -1;
	}

	/**
	 * True if the player is close enough to the island for golems to be worth
	 * simulating. Away from Wyrmscraig the whole plugin should cost nothing.
	 */
	boolean playerNearIsland()
	{
		if (!hasAnchor())
		{
			return false;
		}
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return false;
		}
		for (int regionId : wv.getMapRegions())
		{
			if (withinIsland(regionId))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * True if a region is part of the island.
	 *
	 * <p>A fixed list rather than a radius around the anchor. The bundled map defines
	 * exactly which regions the golems have, so harvesting anything outside it would
	 * accumulate ground they can never reach — and a radius was only ever a guess at
	 * the shape the list now states outright.
	 */
	private boolean withinIsland(int regionId)
	{
		for (int island : GolemContent.ISLAND_REGIONS)
		{
			if (island == regionId)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Copies passability for every island region currently loaded out of the scene.
	 *
	 * <p>Bounded to regions near the anchor so that walking the golems' owner across
	 * the rest of Gielinor does not accumulate a world map in their config.
	 */
	/**
	 * Asks for one more harvest pass. Called when the scene is rebuilt.
	 *
	 * <p>Harvesting used to run every game tick. A region only becomes "done" once
	 * every one of its 4096 tiles has been in the scene at once, which never happens
	 * for the regions clipped by the edge of the scene — so those were re-scanned in
	 * full, several times over, sixty times a minute, forever. Nothing about the scene
	 * changes between ticks, so once per scene load is all it can ever be worth.
	 */
	void sceneChanged()
	{
		pendingHarvest = true;
	}

	private boolean pendingHarvest = true;

	void harvestLoadedRegions()
	{
		if (!pendingHarvest)
		{
			return;
		}
		pendingHarvest = false;

		WorldView wv = client.getTopLevelWorldView();
		if (wv == null || !hasAnchor())
		{
			return;
		}

		CollisionData[] maps = wv.getCollisionMaps();
		int plane = wv.getPlane();
		if (maps == null || plane < 0 || plane >= maps.length || maps[plane] == null)
		{
			return;
		}
		int[][] flags = maps[plane].getFlags();
		if (flags == null)
		{
			return;
		}

		int baseX = wv.getBaseX();
		int baseY = wv.getBaseY();

		for (int regionId : wv.getMapRegions())
		{
			long key = key(regionId, plane);
			if (!withinIsland(regionId) || harvested.contains(key))
			{
				continue;
			}

			long[] bits = regions.computeIfAbsent(key, k -> new long[WORDS_PER_REGION]);
			int regionBaseX = (regionId >> 8) << 6;
			int regionBaseY = (regionId & 0xFF) << 6;
			int tilesSeen = 0;

			for (int rx = 0; rx < REGION_SIZE; rx++)
			{
				for (int ry = 0; ry < REGION_SIZE; ry++)
				{
					int sceneX = regionBaseX + rx - baseX;
					int sceneY = regionBaseY + ry - baseY;
					if (sceneX < 0 || sceneY < 0
						|| sceneX >= Constants.SCENE_SIZE || sceneY >= Constants.SCENE_SIZE
						|| sceneX >= flags.length || sceneY >= flags[sceneX].length)
					{
						continue;
					}

					tilesSeen++;
					int here = flags[sceneX][sceneY];
					if ((here & UNWALKABLE) != 0)
					{
						continue;
					}

					// North and east are each blocked by a wall on this tile or by the
					// destination tile being unstandable. The destination may be outside
					// the scene at a region edge, in which case leave the bit clear and
					// let the neighbouring region's harvest fill it in later.
					if ((here & CollisionDataFlag.BLOCK_MOVEMENT_NORTH) == 0
						&& standable(flags, sceneX, sceneY + 1))
					{
						set(bits, rx, ry, FLAG_NORTH);
					}
					if ((here & CollisionDataFlag.BLOCK_MOVEMENT_EAST) == 0
						&& standable(flags, sceneX + 1, sceneY))
					{
						set(bits, rx, ry, FLAG_EAST);
					}
				}
			}

			if (tilesSeen > 0)
			{
				dirty = true;
			}

			// Only call a region done when every one of its tiles was actually in the
			// scene. The scene is 104 tiles square and regions are 64, so the ones at
			// the edge are always clipped — marking those complete on the first pass
			// would freeze a half-scanned region and leave the golems a map with holes
			// in it that never fill, however often the player walks over them.
			if (tilesSeen == REGION_SIZE * REGION_SIZE)
			{
				harvested.add(key);
				log.debug("Harvested island region {} plane {}", regionId, plane);
			}
		}
	}

	private static boolean standable(int[][] flags, int sceneX, int sceneY)
	{
		if (sceneX < 0 || sceneY < 0
			|| sceneX >= flags.length || flags[sceneX] == null || sceneY >= flags[sceneX].length)
		{
			return false;
		}
		return (flags[sceneX][sceneY] & UNWALKABLE) == 0;
	}

	// ---- querying ----

	/** True if the tile has been harvested and something may stand on it. */
	boolean isKnownWalkable(int worldX, int worldY, int plane)
	{
		// A tile is walkable if it can be left in any direction. An isolated tile with
		// no exits is of no use to a wandering golem anyway.
		return north(worldX, worldY, plane) || east(worldX, worldY, plane)
			|| north(worldX, worldY - 1, plane) || east(worldX - 1, worldY, plane);
	}

	boolean north(int x, int y, int plane)
	{
		return get(x, y, plane, FLAG_NORTH);
	}

	boolean east(int x, int y, int plane)
	{
		return get(x, y, plane, FLAG_EAST);
	}

	/** Can something step one cardinal tile from (x, y)? */
	boolean canStep(int x, int y, int plane, int dx, int dy)
	{
		if (dx == 0 && dy == 1)
		{
			return north(x, y, plane);
		}
		if (dx == 0 && dy == -1)
		{
			return north(x, y - 1, plane);
		}
		if (dx == 1 && dy == 0)
		{
			return east(x, y, plane);
		}
		if (dx == -1 && dy == 0)
		{
			return east(x - 1, y, plane);
		}
		return false;
	}

	private boolean get(int x, int y, int plane, int flag)
	{
		long[] bits = regions.get(key(regionIdOf(x, y), plane));
		if (bits == null)
		{
			return false;
		}
		int bit = bitIndex(x & REGION_MASK, y & REGION_MASK, flag);
		return (bits[bit >> 6] >>> (bit & 63) & 1L) != 0L;
	}

	private static void set(long[] bits, int rx, int ry, int flag)
	{
		int bit = bitIndex(rx, ry, flag);
		bits[bit >> 6] |= 1L << (bit & 63);
	}

	private static int bitIndex(int rx, int ry, int flag)
	{
		return (ry * REGION_SIZE + rx) * FLAGS_PER_TILE + flag;
	}

	private static int regionIdOf(int worldX, int worldY)
	{
		return ((worldX >> 6) << 8) | (worldY >> 6);
	}

	private static long key(int regionId, int plane)
	{
		return ((long) regionId << 8) | (plane & 0xFF);
	}

	// ---- persistence ----

	/**
	 * Encodes the whole memory as one string: anchor, then each region-plane's bits,
	 * gzipped and base64'd.
	 *
	 * <p>Compression is not a nicety. A region is 1KB of flags, an island is several
	 * regions, and a passability map is overwhelmingly long runs of "walkable" — it
	 * deflates to a fraction of that, which is the difference between a config value
	 * and an abuse of one.
	 */
	String serialise()
	{
		try
		{
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			try (GZIPOutputStream gz = new GZIPOutputStream(out);
				 java.io.DataOutputStream data = new java.io.DataOutputStream(gz))
			{
				data.writeInt(anchorRegionId);
				data.writeInt(regions.size());
				for (Map.Entry<Long, long[]> entry : regions.entrySet())
				{
					data.writeLong(entry.getKey());
					for (long word : entry.getValue())
					{
						data.writeLong(word);
					}
				}
			}
			dirty = false;
			return Base64.getEncoder().encodeToString(out.toByteArray());
		}
		catch (IOException e)
		{
			log.warn("Could not save island map", e);
			return "";
		}
	}

	/** Restores a memory previously written by {@link #serialise()}. */
	void deserialise(String encoded)
	{
		regions.clear();
		harvested.clear();
		anchorRegionId = -1;
		dirty = false;

		if (encoded == null || encoded.isEmpty())
		{
			return;
		}

		try (GZIPInputStream gz = new GZIPInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(encoded)));
			 java.io.DataInputStream data = new java.io.DataInputStream(gz))
		{
			anchorRegionId = data.readInt();
			int count = data.readInt();
			for (int i = 0; i < count; i++)
			{
				long key = data.readLong();
				long[] words = new long[WORDS_PER_REGION];
				for (int w = 0; w < WORDS_PER_REGION; w++)
				{
					words[w] = data.readLong();
				}
				regions.put(key, words);
				// Deliberately not added to `harvested`: a restored region is re-scanned
				// once when it next loads, so map edits by Jagex heal themselves.
			}
			log.debug("Loaded island map: anchor {}, {} region-planes", anchorRegionId, count);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Island map unreadable, starting fresh", e);
			regions.clear();
			anchorRegionId = -1;
		}
	}

	/** Throws away everything learned. */
	void forget()
	{
		regions.clear();
		harvested.clear();
		anchorRegionId = -1;
		dirty = true;
	}
}

package com.golemsdontdie;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;

/**
 * Reads and writes the saved golem roster.
 *
 * <p>Only what the cache cannot supply is written: the NPC ID, where the golem is,
 * where it calls home, and the three animation IDs that no composition exposes.
 * Everything visual is re-fetched from the cache on load, so the save stays about
 * ten numbers per golem however elaborate the model is.
 *
 * <p>The format is a flat delimited string rather than JSON. The whole record is
 * numbers, the config store takes a string either way, and a save the player can
 * read and edit in the config file is worth more here than a schema.
 */
@Slf4j
@Singleton
class GolemStore
{
	private static final String GOLEM_SEPARATOR = ";";
	private static final String FIELD_SEPARATOR = ",";

	/** Ten numbers plus the nickname. */
	private static final int FIELD_COUNT = 11;

	/** Characters a nickname may not contain, because they are the separators. */
	private static final String ILLEGAL_IN_NICKNAME = "[;,]";

	@Inject
	private Client client;

	/** A golem as it sits in the save file, before the cache fills in its appearance. */
	static class SavedGolem
	{
		int npcId;
		int worldX;
		int worldY;
		int plane;
		int orientation;
		int homeX;
		int homeY;
		int idlePose;
		int walk;
		int run;
		String nickname;
	}

	/** Encodes a live roster for the config store. */
	String serialise(List<Golem> golems)
	{
		StringBuilder out = new StringBuilder();
		for (Golem golem : golems)
		{
			GolemSnapshot snapshot = golem.getSnapshot();
			WorldPoint at = golem.currentTile();
			if (out.length() > 0)
			{
				out.append(GOLEM_SEPARATOR);
			}
			out.append(snapshot.getNpcId()).append(FIELD_SEPARATOR)
				.append(at.getX()).append(FIELD_SEPARATOR)
				.append(at.getY()).append(FIELD_SEPARATOR)
				.append(golem.getPlane()).append(FIELD_SEPARATOR)
				.append(golem.getOrientation()).append(FIELD_SEPARATOR)
				.append(golem.getHome().getX()).append(FIELD_SEPARATOR)
				.append(golem.getHome().getY()).append(FIELD_SEPARATOR)
				.append(snapshot.getIdlePoseAnimation()).append(FIELD_SEPARATOR)
				.append(snapshot.getWalkAnimation()).append(FIELD_SEPARATOR)
				.append(snapshot.getRunAnimation()).append(FIELD_SEPARATOR)
				// Separators are stripped rather than escaped: a nickname is free text
				// the player types, and losing a stray comma from one is a far smaller
				// problem than a save file that will not parse.
				.append(golem.getNickname() == null
					? ""
					: golem.getNickname().replaceAll(ILLEGAL_IN_NICKNAME, ""));
		}
		return out.toString();
	}

	/** Decodes a roster. Malformed entries are dropped rather than failing the load. */
	List<SavedGolem> deserialise(String encoded)
	{
		List<SavedGolem> result = new ArrayList<>();
		if (encoded == null || encoded.trim().isEmpty())
		{
			return result;
		}

		for (String entry : encoded.split(GOLEM_SEPARATOR))
		{
			if (entry.trim().isEmpty())
			{
				continue;
			}
			// -1 keeps a trailing empty nickname as a field rather than dropping it.
			String[] fields = entry.split(FIELD_SEPARATOR, -1);
			if (fields.length != FIELD_COUNT)
			{
				log.debug("Dropping malformed saved golem '{}'", entry);
				continue;
			}
			try
			{
				SavedGolem saved = new SavedGolem();
				saved.npcId = Integer.parseInt(fields[0].trim());
				saved.worldX = Integer.parseInt(fields[1].trim());
				saved.worldY = Integer.parseInt(fields[2].trim());
				saved.plane = Integer.parseInt(fields[3].trim());
				saved.orientation = Integer.parseInt(fields[4].trim());
				saved.homeX = Integer.parseInt(fields[5].trim());
				saved.homeY = Integer.parseInt(fields[6].trim());
				saved.idlePose = Integer.parseInt(fields[7].trim());
				saved.walk = Integer.parseInt(fields[8].trim());
				saved.run = Integer.parseInt(fields[9].trim());
				String nickname = fields[10].trim();
				saved.nickname = nickname.isEmpty() ? null : nickname;
				result.add(saved);
			}
			catch (NumberFormatException e)
			{
				log.debug("Dropping unparseable saved golem '{}'", entry, e);
			}
		}
		return result;
	}

	/**
	 * Turns a saved record back into a golem, pulling its appearance from the cache.
	 *
	 * @param index position in the save file, which is what keeps each golem's seed
	 *              distinct — see below
	 * @return the golem, or null if the cache no longer knows that NPC ID
	 */
	Golem revive(SavedGolem saved, int index)
	{
		WorldPoint at = new WorldPoint(saved.worldX, saved.worldY, saved.plane);
		GolemSnapshot snapshot = GolemSnapshot.restore(
			client, saved.npcId, saved.idlePose, saved.walk, saved.run, at, saved.orientation);
		if (snapshot == null)
		{
			log.debug("Saved golem npc {} is no longer in the cache", saved.npcId);
			return null;
		}

		WorldPoint home = new WorldPoint(saved.homeX, saved.homeY, saved.plane);

		// The index is what makes the seed unique, and it is not decoration.
		//
		// Position alone is not enough: two golems standing on the same tile when the
		// game was saved would come back with the same seed, and a Golem's entire gait
		// — where it wanders, how long it dwells — comes out of that one number. They
		// would walk in perfect lockstep forever, which is both obviously wrong and
		// exactly what happens where golems congregate, such as on a spawn tile.
		//
		// Position still contributes, so a golem keeps a stable character across
		// reloads as long as the roster does not change around it.
		long seed = ((long) saved.worldX << 32) ^ ((long) saved.worldY << 8) ^ saved.npcId ^ (index * 0x9E3779B9L);
		Golem golem = Golem.onTile(snapshot, home, seed, at);
		golem.setNickname(saved.nickname);
		return golem;
	}
}

package com.golemsdontdie;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Side panel listing every golem, with a name field and a remove button each.
 *
 * <p>A panel rather than config items because the list is not a setting: it grows and
 * shrinks as golems are made and retired, and RuneLite's config UI is generated from a
 * fixed interface. A dynamic list with per-row controls has to be built by hand.
 *
 * <p>It replaces what used to be a "forget saved golems" tick box — an all-or-nothing
 * button that could only ever delete every golem the player had, which is a poor
 * answer to wanting rid of one.
 */
class GolemListPanel extends PluginPanel
{
	private static final Font HEADING = FontManager.getRunescapeBoldFont().deriveFont(18f);
	private static final Font ROW = FontManager.getRunescapeFont().deriveFont(16f);
	private static final Font PLACEHOLDER = ROW.deriveFont(Font.ITALIC);

	/** Dim enough to read as absent text rather than as a name someone chose. */
	private static final Color PLACEHOLDER_COLOUR = new Color(120, 120, 120);

	private final JPanel rows = new JPanel();
	private final JLabel summary = new JLabel();

	/**
	 * Offers to make up the difference when fewer golems are roaming than have been
	 * crafted. Hidden whenever the two agree, which is the normal state.
	 */
	private final JButton revive = new JButton();

	/** Called with the golem to remove when its X is clicked. */
	private final Consumer<Golem> onRemove;

	/** Called when a golem is renamed, so the roster can be saved. */
	private final Runnable onRename;

	/** Called when the revive button is pressed. */
	private final Runnable onRevive;

	/** What is currently displayed, so a rebuild can be skipped when nothing changed. */
	private final List<Long> shown = new ArrayList<>();

	GolemListPanel(Consumer<Golem> onRemove, Runnable onRename, Runnable onRevive)
	{
		super(false);
		this.onRemove = onRemove;
		this.onRename = onRename;
		this.onRevive = onRevive;

		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(16, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		summary.setFont(HEADING);
		summary.setForeground(Color.WHITE);
		summary.setHorizontalAlignment(SwingConstants.CENTER);
		summary.setBorder(BorderFactory.createEmptyBorder(0, 0, 12, 0));

		revive.setFont(ROW);
		revive.setFocusPainted(false);
		revive.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		revive.setForeground(Color.WHITE);
		revive.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		revive.addActionListener(e -> onRevive.run());
		revive.setVisible(false);

		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setBorder(BorderFactory.createEmptyBorder(0, 0, 12, 0));
		header.add(summary, BorderLayout.NORTH);
		header.add(revive, BorderLayout.CENTER);
		add(header, BorderLayout.NORTH);

		rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
		rows.setBackground(ColorScheme.DARK_GRAY_COLOR);

		// Rows are pinned to the top of a filler panel so a short list does not stretch
		// its entries down the whole panel.
		JPanel filler = new JPanel(new BorderLayout());
		filler.setBackground(ColorScheme.DARK_GRAY_COLOR);
		filler.add(rows, BorderLayout.NORTH);

		JScrollPane scroll = new JScrollPane(filler,
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		add(scroll, BorderLayout.CENTER);
	}

	/**
	 * Redraws the list.
	 *
	 * <p>Rebuilt only when the set of golems actually changes. This is called every
	 * game tick, and tearing down and recreating a text field the player might be
	 * typing in would make renaming impossible.
	 */
	/**
	 * Redraws the list.
	 *
	 * @param missing how many fewer golems are roaming than have been crafted; the
	 *                revive button shows only when this is positive
	 */
	void refresh(List<Golem> golems, int missing)
	{
		SwingUtilities.invokeLater(() ->
		{
			updateRevive(missing);

			List<Long> ids = new ArrayList<>(golems.size());
			for (Golem golem : golems)
			{
				ids.add(golem.getId());
			}
			if (ids.equals(shown))
			{
				updateSummary(golems.size());
				return;
			}

			shown.clear();
			shown.addAll(ids);
			rows.removeAll();

			for (Golem golem : golems)
			{
				rows.add(row(golem));
			}

			updateSummary(golems.size());
			rows.revalidate();
			rows.repaint();
		});
	}

	/**
	 * Shows or hides the revive button.
	 *
	 * <p>Only present when there is something to revive, so in ordinary play it is not
	 * there at all — a button that does nothing most of the time is worse than no
	 * button.
	 */
	private void updateRevive(int missing)
	{
		boolean show = missing > 0;
		if (show)
		{
			revive.setText("Revive missing golems (" + missing + ")");
		}
		if (revive.isVisible() != show)
		{
			revive.setVisible(show);
			revalidate();
			repaint();
		}
	}

	private void updateSummary(int count)
	{
		summary.setText(count == 0
			? "No golems yet"
			: count + (count == 1 ? " golem" : " golems") + " unleashed");
	}

	private JPanel row(Golem golem)
	{
		JPanel panel = new JPanel(new BorderLayout(6, 0));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 6));
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));

		JTextField name = new PlaceholderField(golem.getNickname());
		name.setToolTipText("Name this golem");
		name.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				rename();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				rename();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				rename();
			}

			private void rename()
			{
				String text = name.getText().trim();
				golem.setNickname(text.isEmpty() ? null : text);
				onRename.run();
			}
		});
		panel.add(name, BorderLayout.CENTER);

		JButton remove = new JButton("✕");
		remove.setToolTipText("Remove this golem");
		remove.setFont(ROW);
		remove.setFocusPainted(false);
		remove.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		remove.setForeground(Color.LIGHT_GRAY);
		remove.setBorder(BorderFactory.createEmptyBorder(2, 8, 2, 8));
		remove.addActionListener(e -> onRemove.accept(golem));
		panel.add(remove, BorderLayout.EAST);

		// Spacing between rows, which a BoxLayout will not do on its own.
		JPanel spaced = new JPanel(new BorderLayout());
		spaced.setBackground(ColorScheme.DARK_GRAY_COLOR);
		spaced.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		spaced.setMaximumSize(new Dimension(Integer.MAX_VALUE, 46));
		spaced.add(panel, BorderLayout.CENTER);
		return spaced;
	}

	/**
	 * A text field that shows dimmed italic prompt text while it is empty.
	 *
	 * <p>Swing has no placeholder of its own, and the obvious workaround — putting the
	 * prompt in as real text and clearing it on focus — is wrong here: that text would
	 * be indistinguishable from a name, and would be saved as one the moment anything
	 * else read the field. Drawing it instead means the field is genuinely empty until
	 * the player types.
	 */
	private static final class PlaceholderField extends JTextField
	{
		private static final String PROMPT = "Unnamed Golem";

		PlaceholderField(String initial)
		{
			super(initial == null ? "" : initial);
			setFont(ROW);
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
			setForeground(Color.WHITE);
			setCaretColor(Color.WHITE);
			setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			super.paintComponent(g);

			if (!getText().isEmpty())
			{
				return;
			}

			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
					RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
				g2.setFont(PLACEHOLDER);
				g2.setColor(PLACEHOLDER_COLOUR);

				// Sat on the same baseline the real text uses, so the prompt does not
				// jump when the player starts typing over it.
				int x = getInsets().left;
				int y = (getHeight() - g2.getFontMetrics().getHeight()) / 2
					+ g2.getFontMetrics().getAscent();
				g2.drawString(PROMPT, x, y);
			}
			finally
			{
				g2.dispose();
			}
		}
	}
}

package com.golemsdontdie;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * How many golems the player has ever crafted, read from the game's own chat messages.
 *
 * <p>This exists because the plugin's roster is not the same thing as the player's
 * history. Golems made before the plugin was installed were never taken over, and ones
 * culled by the limit or dismissed by hand are gone — so the number wandering the
 * island can fall behind the number actually crafted. The gap is what the revive button
 * offers to close.
 *
 * <p>The total only ever goes up. A message reporting a lower figure than one already
 * seen is treated as not being the message we are looking for, rather than as the count
 * going backwards: golems crafted is a lifetime tally, and misreading some other line as
 * a smaller total would silently make the revive button offer too few golems.
 *
 * <p>The game reports the running total on every craft, so a stale count — from crafting
 * with the plugin disabled, or from a fresh install — corrects itself the next time a
 * golem is finished. Counting golem spawns instead was tried and dropped: on a shared
 * island it would tally other players' golems as the player's own.
 */
@Slf4j
@Singleton
class GolemTally
{
	/** Config key for the running total. Plugin-written, so not a config item. */
	static final String TOTAL_KEY = "totalGolemsCrafted";

	/**
	 * The game's own tally line, sent each time a golem is finished:
	 * <pre>You have crafted 374 golems on Wyrmscraig.</pre>
	 *
	 * <p>Matched precisely rather than by keywords. A loose "a golem and a number" test
	 * would read "You need 5 stone chunks to build a golem" as a total of five, and the
	 * cost of a wrong match here is the revive button offering the wrong number of
	 * golems — so the pattern only accepts the sentence that actually reports the total.
	 * The trailing "on Wyrmscraig" is not required, in case the same line is reused
	 * elsewhere.
	 */
	private static final Pattern TOTAL_MESSAGE =
		Pattern.compile("(?i)\\byou have crafted\\s+([\\d,]+)\\s+golems?\\b");

	@Inject
	private ConfigManager configManager;

	/** Golems crafted, ever. Zero until a message says otherwise. */
	@Getter
	private int total;

	void load()
	{
		total = 0;
		String stored = configManager.getConfiguration(GolemsDontDieConfig.GROUP, TOTAL_KEY);
		if (stored == null || stored.trim().isEmpty())
		{
			return;
		}
		try
		{
			total = Math.max(0, Integer.parseInt(stored.trim()));
		}
		catch (NumberFormatException e)
		{
			log.debug("Stored golem total '{}' unreadable", stored);
		}
	}

	/**
	 * Offers a chat line to the tally.
	 *
	 * @return true if the total changed, so the panel can be redrawn
	 */
	boolean observe(String message)
	{
		if (message == null || message.isEmpty())
		{
			return false;
		}

		Matcher matcher = TOTAL_MESSAGE.matcher(message);
		if (!matcher.find())
		{
			return false;
		}

		int found;
		try
		{
			found = Integer.parseInt(matcher.group(1).replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			// A number too large for an int is not a golem count.
			return false;
		}

		return setTotal(found);
	}

	/**
	 * Raises the total. Ignores anything that would lower it.
	 *
	 * @return true if the total changed
	 */
	boolean setTotal(int candidate)
	{
		if (candidate <= total)
		{
			return false;
		}
		total = candidate;
		configManager.setConfiguration(GolemsDontDieConfig.GROUP, TOTAL_KEY, total);
		log.debug("Golems crafted total is now {}", total);
		return true;
	}

}

package com.golemsdontdie;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Model;
import net.runelite.api.NPC;
import net.runelite.api.Renderable;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

/**
 * Keeps crafted golems alive by replacing each one with a client-side copy, so it
 * wanders Wyrmscraig indefinitely instead of crumbling after half a minute.
 *
 * <p>The handover happens as the golem finishes stepping off its plinth — the one
 * moment it is reliably standing still, so the copy inherits a position and heading
 * with no half-finished step to reconcile. The original is hidden from that point on
 * and crumbles unseen.
 *
 * <p>Copies are simulated in world coordinates, walking and pausing and turning under
 * their own steam, and are drawn only while inside the loaded scene. That separation
 * is what lets a golem wander off the edge of what is loaded and come back later:
 * leaving the scene costs it its renderer, not its existence. Nothing is simulated at
 * all while the player is away from the island.
 *
 * <p>Purely cosmetic. Nothing here sends anything to the server, and the copies are
 * visible only to the player running the plugin.
 *
 * @see IslandMemory for the island's passability map
 * @see Golem for the simulation
 * @see FakeGolem for the drawing
 */
@Slf4j
@PluginDescriptor(
	name = "Golems Don't Die",
	description = "Makes Golems live and wander around forever instead of dying",
	tags = {"golem", "crafting", "wyrmscraig", "skilling", "cosmetic", "npc"}
)
public class GolemsDontDiePlugin extends Plugin
{
	/** Game ticks between position saves. Two minutes: cheap, and bounds what a crash costs. */
	private static final int SAVE_INTERVAL_TICKS = 200;

	/**
	 * Path searches allowed per frame across all golems. At 50fps this is 200 a
	 * second, far more than a roaming population actually asks for, while still
	 * capping the worst frame.
	 */
	private static final int PATH_SEARCHES_PER_FRAME = 4;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private RenderCallbackManager renderCallbacks;

	@Inject
	private ConfigManager configManager;

	@Inject
	private GolemsDontDieConfig config;

	@Inject
	private GolemDetector detector;

	@Inject
	private GolemModelFactory modelFactory;

	@Inject
	private GolemPathfinder pathfinder;

	@Inject
	private IslandMemory islandMemory;

	@Inject
	private GolemStore store;

	@Inject
	private GolemMenu menu;

	@Inject
	private GolemTally tally;

	private final List<Golem> golems = new ArrayList<>();

	/** Real NPCs hidden because a copy has taken over from them. */
	private final Set<Integer> hiddenNpcs = new HashSet<>();

	/** Saved golems waiting for the cache to become readable. */
	private final List<GolemStore.SavedGolem> pendingRestore = new ArrayList<>();

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private GolemMinimapOverlay minimapOverlay;

	private GolemListPanel panel;
	private NavigationButton navButton;

	/**
	 * Hides the real golem once its copy has taken over.
	 *
	 * <p>Registered once at start-up and unregistered once at shutdown, never from an
	 * event handler — a registration that outlives the plugin because an event did not
	 * fire as expected would leave NPCs invisible with nothing left to un-hide them.
	 */
	private final RenderCallback drawCallback = new RenderCallback()
	{
		@Override
		public boolean addEntity(Renderable renderable, boolean ui)
		{
			return shouldDraw(renderable);
		}
	};

	private boolean callbackRegistered = false;

	private int lastGameCycle = -1;
	private int ticksSinceSave = 0;

	/** Set when a golem is added, removed or restored, so the panel redraws once. */
	private boolean rosterChanged = true;

	@Provides
	GolemsDontDieConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GolemsDontDieConfig.class);
	}

	@Override
	protected void startUp()
	{
		// Saved map first, then the shipped baseline underneath it — anything the
		// player has actually walked beats a static export of the same ground.
		islandMemory.deserialise(configManager.getConfiguration(GolemsDontDieConfig.GROUP, IslandMemory.MAP_KEY));
		islandMemory.loadBundled();

		pendingRestore.addAll(store.deserialise(
			configManager.getConfiguration(GolemsDontDieConfig.GROUP, GolemsDontDieConfig.SAVED_GOLEMS_KEY)));

		tally.load();

		// All three panel callbacks arrive on the Swing thread and touch the roster, so
		// each hops to the client thread — the list is owned there.
		panel = new GolemListPanel(
			golem -> clientThread.invoke(() -> removeGolem(golem)),
			() -> clientThread.invoke(this::saveGolems),
			() -> clientThread.invoke(this::reviveMissing));
		navButton = NavigationButton.builder()
			.tooltip("Golems")
			.icon(ImageUtil.loadImageResource(GolemsDontDiePlugin.class, "/golem-icon.png"))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(minimapOverlay);

		renderCallbacks.register(drawCallback);
		callbackRegistered = true;

		lastGameCycle = -1;
		clientThread.invokeLater(this::restorePending);
	}

	@Override
	protected void shutDown()
	{
		// Save before tearing down, or a shutdown would be indistinguishable from
		// deleting every golem the player has.
		saveGolems();
		saveIslandMemory();

		clientThread.invoke(() ->
		{
			for (Golem golem : golems)
			{
				detachRenderer(golem);
			}
			golems.clear();
		});

		overlayManager.remove(minimapOverlay);

		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		panel = null;

		pendingRestore.clear();
		hiddenNpcs.clear();
		detector.reset();
		modelFactory.clear();

		if (callbackRegistered)
		{
			renderCallbacks.unregister(drawCallback);
			callbackRegistered = false;
		}
	}

	// ---- watching the real golems ----

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		if (!detector.isGolem(npc))
		{
			return;
		}

		detector.track(npc);
		islandMemory.anchorAt(npc.getWorldLocation());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		if (tally.observe(event.getMessage()))
		{
			rosterChanged = true;
		}
	}

	/**
	 * Brings the roster back up to the number of golems ever crafted.
	 *
	 * <p>Revived golems are placed on the plinth and disperse on their own, exactly as
	 * a freshly made one would. They are new golems standing in for lost ones rather
	 * than the originals restored — nothing about a golem that was culled or never
	 * tracked survives to be brought back.
	 */
	private void reviveMissing()
	{
		int missing = tally.getTotal() - livingGolems().size();
		if (missing <= 0)
		{
			return;
		}

		WorldPoint plinth = new WorldPoint(GolemContent.PLINTH_X, GolemContent.PLINTH_Y, 0);
		int revived = 0;

		for (int i = 0; i < missing; i++)
		{
			GolemSnapshot snapshot = GolemSnapshot.restore(
				client, GolemContent.GOLEM_NPC_ID,
				GolemContent.GOLEM_IDLE_ANIMATION, GolemContent.GOLEM_WALK_ANIMATION, -1,
				plinth, 0);
			if (snapshot == null)
			{
				log.debug("Cannot revive golems: npc {} not in cache", GolemContent.GOLEM_NPC_ID);
				break;
			}

			// Seeded off a counter as well as the tile so a batch revived onto one
			// square does not walk away in lockstep.
			long seed = ((long) plinth.getX() << 32) ^ ((long) plinth.getY() << 8)
				^ ((golems.size() + i) * 0x9E3779B9L);
			golems.add(Golem.onTile(snapshot, plinth, seed, plinth));
			revived++;
		}

		if (revived > 0)
		{
			rosterChanged = true;
			saveGolems();
			log.debug("Revived {} golems", revived);
		}
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (!(event.getActor() instanceof NPC))
		{
			return;
		}
		NPC npc = (NPC) event.getActor();
		if (!detector.isGolem(npc))
		{
			return;
		}

		int animation = npc.getAnimation();
		if (detector.wasReplaced(npc))
		{
			return;
		}

		// The handover happens as the golem finishes stepping off its plinth, not when
		// it crumbles.
		//
		// Waiting for the crumble meant taking over from a golem that was usually
		// mid-stride, and a copy handed a walk it did not start has to reconcile a
		// position, a heading and a half-finished step all at once. Taking over at the
		// one moment the golem is reliably standing still — the tick the plinth
		// animation ends — means there is nothing to reconcile. The original is hidden
		// for the rest of its short life and crumbles unseen.
		if (animation == -1 && detector.hasLeftPlinth(npc))
		{
			replace(npc);
			return;
		}

		if (animation == GolemContent.GOLEM_SPAWN_ANIMATION)
		{
			detector.noteLeftPlinth(npc);
		}

		// Fallback. If a golem is somehow never seen stepping off — the player arrived
		// mid-life, or the spawn animation was missed — the crumble is still a valid
		// moment to take over, and a jump is better than losing the golem.
		if (detector.isDeathAnimation(animation))
		{
			replace(npc);
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		NPC npc = event.getNpc();
		if (!detector.isGolem(npc))
		{
			return;
		}

		hiddenNpcs.remove(npc.getIndex());
		detector.forget(npc);
	}

	/**
	 * Takes over from a live golem: builds the copy, and hides the original from this
	 * moment on.
	 *
	 * <p>The copy is placed at the NPC's <i>local</i> location, not its world tile.
	 * That distinction is the whole difference between a seamless handover and a
	 * visible jump: {@link NPC#getWorldLocation()} returns the tile the golem is
	 * moving onto, so a golem caught mid-step hands over a destination it has not
	 * reached yet and the copy appears to teleport there. {@link NPC#getLocalLocation()}
	 * is the interpolated position actually being drawn.
	 */
	private void replace(NPC npc)
	{
		if (!hasRoomForAnother())
		{
			// Every slot is spoken for by a named golem. Leave this one alone and let
			// the game play out its own death.
			detector.markReplaced(npc);
			return;
		}

		GolemSnapshot snapshot = detector.snapshotOf(npc);
		if (snapshot == null)
		{
			snapshot = GolemSnapshot.of(npc);
		}
		if (snapshot == null)
		{
			log.debug("No usable snapshot for golem {}, letting it die", npc.getId());
			return;
		}

		WorldView wv = client.getTopLevelWorldView();
		LocalPoint local = npc.getLocalLocation();
		if (wv == null || local == null)
		{
			return;
		}

		// Local coordinates are scene-relative; the simulation is world-absolute.
		int fineX = local.getX() + wv.getBaseX() * Golem.TILE;
		int fineY = local.getY() + wv.getBaseY() * Golem.TILE;

		WorldPoint home = npc.getWorldLocation();
		long seed = ((long) home.getX() << 32) ^ ((long) home.getY() << 8) ^ npc.getIndex();

		// Orientation is taken live rather than from the snapshot, so the copy starts
		// facing exactly where the original was facing on this frame.
		GolemSnapshot posed = snapshot.facing(npc.getCurrentOrientation());
		Golem golem = new Golem(posed, home, seed, fineX, fineY);

		golems.add(golem);
		rosterChanged = true;
		enforceGolemLimit();

		detector.markReplaced(npc);
		hiddenNpcs.add(npc.getIndex());
		saveGolems();
	}

	/**
	 * Retires the oldest unnamed golems until the roster is inside the limit.
	 *
	 * <p>Unlimited by default. A golem costs an animated model drawn each frame, so a
	 * cap is worth having available, but choosing it for the player would quietly
	 * delete golems they had collected on purpose.
	 *
	 * <p><b>Named golems are never culled</b>, even when that leaves the roster over
	 * the limit. A name is the one unambiguous signal that the player cares about a
	 * particular golem, and a performance setting silently deleting the one they called
	 * Dave would be indefensible. Better to sit above the cap.
	 *
	 * <p>Retired golems crumble rather than vanishing; the roster is trimmed when the
	 * animation finishes.
	 */
	private void enforceGolemLimit()
	{
		if (!config.limitGolems())
		{
			return;
		}

		int limit = Math.max(1, config.maxGolems());
		int alive = countLiving();

		for (Golem golem : golems)
		{
			if (alive <= limit)
			{
				break;
			}
			if (golem.isDying() || isNamed(golem))
			{
				continue;
			}
			golem.startDying();
			alive--;
		}
	}

	/**
	 * The roster as anything outside the client thread should see it: a copy, with
	 * golems that are mid-crumble already gone.
	 *
	 * <p>A copy because the panel reads it on the Swing thread while this one keeps
	 * changing it. Crumbling golems are excluded so that pressing ✕ removes the entry
	 * at once rather than leaving it listed for the two seconds it takes to fall apart.
	 */
	private List<Golem> livingGolems()
	{
		List<Golem> living = new ArrayList<>(golems.size());
		for (Golem golem : golems)
		{
			if (!golem.isDying())
			{
				living.add(golem);
			}
		}
		return living;
	}

	/** Golems not already crumbling. A dying golem is on its way out and does not count. */
	private int countLiving()
	{
		int alive = 0;
		for (Golem golem : golems)
		{
			if (!golem.isDying())
			{
				alive++;
			}
		}
		return alive;
	}

	private static boolean isNamed(Golem golem)
	{
		String name = golem.getNickname();
		return name != null && !name.isEmpty();
	}

	/**
	 * Whether a new golem can be taken over.
	 *
	 * <p>False when the roster is full of golems the player has named: there is nothing
	 * to make room with, and culling a named golem is not on the table. In that case the
	 * plugin stands aside entirely and lets the real golem live out its twenty seconds
	 * and crumble, which is the honest outcome — better than taking one over and
	 * immediately killing something else to pay for it.
	 */
	private boolean hasRoomForAnother()
	{
		if (!config.limitGolems())
		{
			return true;
		}
		if (countLiving() < Math.max(1, config.maxGolems()))
		{
			return true;
		}
		for (Golem golem : golems)
		{
			if (!golem.isDying() && !isNamed(golem))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Retires one golem, from the side panel's X button. Client thread only.
	 *
	 * <p>It crumbles rather than vanishing, and leaves the roster when the animation
	 * finishes. The panel drops it from the list straight away so the button feels
	 * immediate — the golem the player is watching is on its way out either way.
	 */
	private void removeGolem(Golem golem)
	{
		golem.startDying();
		rosterChanged = true;
		saveGolems();
	}

	// ---- simulation ----

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		if (golems.isEmpty())
		{
			return;
		}

		int cycle = client.getGameCycle();
		int elapsed = lastGameCycle < 0 ? 0 : cycle - lastGameCycle;
		lastGameCycle = cycle;

		// A negative or absurd delta means the cycle counter was reset by a world hop
		// or a reconnect. Skip that frame rather than teleporting every golem.
		if (elapsed < 0 || elapsed > 200)
		{
			elapsed = 0;
		}

		boolean nearIsland = islandMemory.playerNearIsland();

		// Path searches are rationed per frame. A golem only searches when it finishes
		// a walk, which is rare individually — but with hundreds of them the arrivals
		// bunch up, and a frame that runs fifty breadth-first searches is a visible
		// stutter. Golems denied a search simply stand still for a frame and ask again,
		// which is indistinguishable from the pause they take between walks anyway.
		int searchBudget = PATH_SEARCHES_PER_FRAME;

		// Resolved once rather than per golem. Both of these were being fetched or
		// built five hundred times a frame to produce the same answer.
		WorldView wv = client.getTopLevelWorldView();

		for (Golem golem : golems)
		{
			if (nearIsland && elapsed > 0)
			{
				if (golem.advance(elapsed, islandMemory, pathfinder, searchBudget > 0))
				{
					searchBudget--;
				}
			}
			updateRenderer(golem, wv, nearIsland);
		}

		reapCrumbled();
	}

	/**
	 * Drops golems whose crumble has finished.
	 *
	 * <p>Separate from the loop above so the roster is not modified while it is being
	 * walked.
	 */
	private void reapCrumbled()
	{
		for (Iterator<Golem> it = golems.iterator(); it.hasNext(); )
		{
			Golem golem = it.next();
			if (golem.isCrumbled())
			{
				detachRenderer(golem);
				it.remove();
				rosterChanged = true;
			}
		}
	}

	/**
	 * Attaches or detaches a golem's drawn object as it crosses the scene boundary.
	 *
	 * <p>This is what lets a golem wander off the edge of what is loaded and come back
	 * later: leaving the scene costs it its renderer, not its existence.
	 */
	private void updateRenderer(Golem golem, WorldView wv, boolean nearIsland)
	{
		boolean visible = nearIsland
			&& wv != null
			&& wv.getPlane() == golem.getPlane()
			&& inScene(wv, golem);

		if (!visible)
		{
			detachRenderer(golem);
			return;
		}

		if (golem.getRenderer() == null)
		{
			Model model = modelFactory.modelFor(golem.getSnapshot());
			if (model == null)
			{
				return;
			}
			FakeGolem renderer = new FakeGolem(client, golem, model, modelFactory);
			golem.setRenderer(renderer);
			client.registerRuneLiteObject(renderer);
		}
	}

	private boolean inScene(WorldView wv, Golem golem)
	{
		return Golem.isInScene(wv,
			golem.getFineX() - wv.getBaseX() * Golem.TILE,
			golem.getFineY() - wv.getBaseY() * Golem.TILE);
	}

	private void detachRenderer(Golem golem)
	{
		FakeGolem renderer = golem.getRenderer();
		if (renderer != null)
		{
			client.removeRuneLiteObject(renderer);
			golem.setRenderer(null);
		}
	}

	// ---- per-tick upkeep ----

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// Snapshots are refreshed continuously rather than read once at spawn: a golem
		// steps off its plinth and starts walking, and the pose animations it is given
		// are not necessarily the ones it had while standing on it.
		WorldView topLevel = client.getTopLevelWorldView();
		if (topLevel != null)
		{
			for (NPC npc : topLevel.npcs())
			{
				if (detector.isGolem(npc) && !detector.wasReplaced(npc))
				{
					detector.track(npc);
				}
			}
		}

		islandMemory.harvestLoadedRegions();

		// Only when the roster has actually changed. Copying five hundred golems every
		// tick to hand the panel a list it would find identical is work for nothing,
		// and the roster changes when a golem is made or removed — not on a timer.
		if (panel != null && rosterChanged)
		{
			rosterChanged = false;
			List<Golem> living = livingGolems();
			panel.refresh(living, tally.getTotal() - living.size());
		}

		if (++ticksSinceSave >= SAVE_INTERVAL_TICKS)
		{
			ticksSinceSave = 0;
			saveGolems();
			saveIslandMemory();
		}
	}

	/**
	 * Offers the hovered golem's menu entries.
	 *
	 * <p>On client tick rather than game tick: this is when the client rebuilds its
	 * menu, and a golem that had to wait up to 600ms to become hoverable would feel
	 * broken next to a real NPC.
	 */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (!golems.isEmpty())
		{
			menu.addEntries(golems);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();

		if (state == GameState.LOADING)
		{
			// The scene is being rebuilt, so every registered object is about to refer
			// to coordinates that no longer mean what they did. Drop the renderers; the
			// golems themselves are in world space and are unaffected.
			for (Golem golem : golems)
			{
				detachRenderer(golem);
			}
			lastGameCycle = -1;
			islandMemory.sceneChanged();
			return;
		}

		if (state == GameState.LOGGED_IN)
		{
			restorePending();
			return;
		}

		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			// Golems are always permanent, so nothing is released here — only the
			// renderers, which belong to a scene that is going away.
			saveGolems();
			saveIslandMemory();
			detector.reset();
			hiddenNpcs.clear();
			lastGameCycle = -1;

			for (Golem golem : golems)
			{
				detachRenderer(golem);
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!GolemsDontDieConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if ("maxGolems".equals(event.getKey()) || "limitGolems".equals(event.getKey()))
		{
			clientThread.invoke(() ->
			{
				enforceGolemLimit();
				saveGolems();
			});
		}
	}

	// ---- persistence ----

	private void restorePending()
	{
		if (pendingRestore.isEmpty() || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		List<GolemStore.SavedGolem> saved = new ArrayList<>(pendingRestore);
		for (int i = 0; i < saved.size(); i++)
		{
			Golem golem = store.revive(saved.get(i), i);
			if (golem != null)
			{
				golems.add(golem);
				rosterChanged = true;
			}
		}
		pendingRestore.clear();
		enforceGolemLimit();
		log.debug("Restored {} saved golems", golems.size());
	}

	/**
	 * Writes the roster out.
	 *
	 * <p>Golems mid-crumble are excluded — they have been retired, and saving them
	 * would bring them back alive on the next login.
	 */
	private void saveGolems()
	{
		configManager.setConfiguration(
			GolemsDontDieConfig.GROUP, GolemsDontDieConfig.SAVED_GOLEMS_KEY, store.serialise(livingGolems()));
	}

	private void saveIslandMemory()
	{
		if (!islandMemory.isDirty())
		{
			return;
		}
		configManager.setConfiguration(
			GolemsDontDieConfig.GROUP, IslandMemory.MAP_KEY, islandMemory.serialise());
	}

	// ---- hiding the original ----

	/**
	 * Hides a real golem once its copy has taken over.
	 *
	 * <p>Both exist for the rest of the original's short life — it steps off the
	 * plinth, the copy takes over, and the original keeps walking and then crumbles
	 * where the player cannot see it. Without this there would visibly be two.
	 */
	private boolean shouldDraw(Renderable renderable)
	{
		if (hiddenNpcs.isEmpty() || !(renderable instanceof NPC))
		{
			return true;
		}
		return !hiddenNpcs.contains(((NPC) renderable).getIndex());
	}

	/**
	 * The current roster, for the overlays.
	 *
	 * <p>The live list, not a copy: this is read once per frame by the minimap overlay
	 * and copying it every time would allocate for nothing. Both the overlay and the
	 * list are touched only on the client thread.
	 */
	List<Golem> activeGolems()
	{
		return golems;
	}
}

package com.golemsdontdie;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Launches a developer-mode client with this plugin loaded, for testing in game.
 *
 * <p>Not a test despite the name and the location — {@code Launch-Plugin.ps1} derives
 * this class by appending "Test" to the plugin class from
 * {@code runelite-plugin.properties}, and runs its {@code main}. It lives in the test
 * source set so it is compiled but never shipped in the plugin jar.
 */
public class GolemsDontDiePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(GolemsDontDiePlugin.class);
		RuneLite.main(args);
	}
}
